import{r as e}from"./rolldown-runtime-BCiCTKAo.js";var t=[{id:`discours-indirect`,title:`Rapporte les paroles`,en:`Report what was said`,level:3,items:[{id:`conseiller-de`,fr:`Le médecin m'a conseillé ____ moins de café.`,cue:`(« Buvez moins de café. »)`,answer:`de boire`,wrong:[`boire`,`que je bois`,`à boire`,`buvez`],en:`The doctor advised me to drink less coffee.`,why:`Advice or an order becomes de + infinitive.`},{id:`demander-de-ne-pas`,fr:`La guide nous a demandé ____ les œuvres.`,cue:`(« Ne touchez pas les œuvres. »)`,answer:`de ne pas toucher`,wrong:[`de ne toucher pas`,`ne pas toucher`,`de pas toucher`,`de ne touchez pas`],en:`The guide asked us not to touch the works of art.`,why:`A negative order: de ne pas + infinitive, with ne pas together.`},{id:`de-ne-jamais`,fr:`Mon père m'a toujours dit ____ les gens sur les apparences.`,cue:`(« Ne juge jamais les gens sur les apparences. »)`,answer:`de ne jamais juger`,wrong:[`de jamais juger`,`ne jamais juger`,`de ne jamais juge`,`de ne juges jamais`],en:`My father always told me never to judge people by appearances.`,why:`De ne jamais + infinitive: ne and jamais both go before the infinitive.`},{id:`dire-de-attendre`,fr:`Elle m'a dit ____ devant la gare.`,cue:`(« Attends-moi devant la gare. »)`,answer:`de l'attendre`,wrong:[`que je l'attendais`,`l'attendre`,`de m'attendre`,`à l'attendre`],en:`She told me to wait for her outside the station.`,why:`Dire de + infinitive reports an order; dire que reports a statement.`},{id:`demander-de-lui`,fr:`Ma cheffe m'a demandé ____ le dossier avant midi.`,cue:`(« Envoie-moi le dossier avant midi. »)`,answer:`de lui envoyer`,wrong:[`de m'envoyer`,`lui envoyer`,`d'envoyer-lui`,`de lui envoie`],en:`My boss asked me to send her the file before noon.`,why:`The moi in her order refers to her: de lui envoyer.`},{id:`demander-de-aider`,fr:`Ma collègue m'a demandé ____ pour son exposé.`,cue:`(« Tu peux m'aider ? »)`,answer:`de l'aider`,accept:[`si je pouvais l'aider`],wrong:[`de m'aider`,`de lui aider`,`l'aider`],en:`My colleague asked me to help her with her presentation.`,why:`A request becomes demander de + infinitive; aider takes a direct object (l').`},{id:`question-si`,fr:`Mon voisin m'a demandé ____ j'avais vu son chat.`,cue:`(« Tu as vu mon chat ? »)`,answer:`si`,wrong:[`est-ce que`,`que`,`ce que`,`qu'est-ce que`],en:`My neighbour asked me if I had seen his cat.`,why:`A yes/no question is reported with si.`},{id:`question-ou`,fr:`Le chauffeur de taxi m'a demandé ____ je voulais aller.`,cue:`(« Où voulez-vous aller ? »)`,answer:`où`,wrong:[`où est-ce que`,`si`,`que`,`ce que`],en:`The taxi driver asked me where I wanted to go.`,why:`Où stays où, with no est-ce que and no inversion.`},{id:`question-ce-que`,fr:`Le journaliste lui a demandé ____ pensait de la réforme.`,answer:`ce qu'il`,wrong:[`qu'est-ce qu'il`,`ce qui`,`qu'il`,`s'il`],en:`The journalist asked him what he thought of the reform.`,why:`Qu'est-ce que becomes ce que in reported speech.`},{id:`question-ce-qui`,fr:`Elle voulait savoir ____ s'était passé pendant son absence.`,answer:`ce qui`,accept:[`ce qu'il`],wrong:[`qu'est-ce qui`,`ce que`,`qu'est-ce que`,`que`],en:`She wanted to know what had happened while she was away.`,why:`Qu'est-ce qui becomes ce qui (ce qu'il also works with se passer).`},{id:`te-me`,fr:`Ma sœur m'a dit qu'elle ____ prêtait sa voiture pour le week-end.`,cue:`(« Je te prête ma voiture. »)`,answer:`me`,wrong:[`te`,`lui`,`se`,`la`],en:`My sister told me she was lending me her car for the weekend.`,why:`The te in her words means me, the person reporting.`},{id:`possessif-son`,fr:`Paul m'a téléphoné pour me dire qu'il avait oublié ____ badge au bureau.`,cue:`(« J'ai oublié mon badge. »)`,answer:`son`,wrong:[`mon`,`ton`,`sa`,`leur`],en:`Paul called to tell me he had left his pass at the office.`,why:`The mon in Paul's words becomes son.`},{id:`vos-nos`,fr:`Le directeur nous a assuré que ____ postes seraient maintenus.`,cue:`(« Vos postes seront maintenus. »)`,answer:`nos`,wrong:[`vos`,`leurs`,`ses`,`nous`],en:`The director assured us that our jobs would be kept.`,why:`Vos (said to us) becomes nos when we report it.`},{id:`demain-lendemain`,fr:`Il y a un mois, Sophie m'a dit qu'elle signerait le contrat ____ ; je l'attends toujours.`,cue:`(demain)`,answer:`le lendemain`,accept:[`le jour suivant`],wrong:[`demain`,`la veille`,`le jour même`,`hier`],en:`A month ago, Sophie told me she'd sign the contract the next day; I'm still waiting.`,why:`Reported later, demain becomes le lendemain.`},{id:`hier-veille`,fr:`Quand je l'ai revu en juin, il m'a raconté qu'il avait passé un entretien ____.`,cue:`(hier)`,answer:`la veille`,accept:[`le jour précédent`,`le jour d'avant`],wrong:[`hier`,`le lendemain`,`avant-hier`,`l'avant-veille`],en:`When I saw him again in June, he told me he had had an interview the day before.`,why:`Reported later, hier becomes la veille.`},{id:`aujourdhui-ce-jour-la`,fr:`Le 3 mai, la ministre a déclaré qu'elle recevrait les syndicats ____.`,cue:`(aujourd'hui)`,answer:`ce jour-là`,accept:[`le jour même`],wrong:[`aujourd'hui`,`le lendemain`,`la veille`],en:`On 3 May, the minister announced that she would meet the unions that day.`,why:`Aujourd'hui becomes ce jour-là.`},{id:`ce-soir-la`,fr:`Lundi, elle m'a écrit qu'elle passerait ____, mais elle n'est jamais venue.`,cue:`(ce soir)`,answer:`ce soir-là`,wrong:[`ce soir`,`le lendemain soir`,`hier soir`,`la veille au soir`],en:`On Monday she wrote that she would drop by that evening, but she never came.`,why:`Ce soir becomes ce soir-là.`},{id:`semaine-suivante`,fr:`En mars, la mairie avait annoncé que les travaux commenceraient ____.`,cue:`(la semaine prochaine)`,answer:`la semaine suivante`,accept:[`la semaine d'après`],wrong:[`la semaine prochaine`,`la semaine dernière`,`la semaine précédente`,`cette semaine-là`],en:`In March, the town hall had announced that the work would start the following week.`,why:`La semaine prochaine becomes la semaine suivante.`},{id:`semaine-precedente`,fr:`Quand je l'ai croisée l'an dernier, elle m'a expliqué qu'elle avait démissionné ____.`,cue:`(la semaine dernière)`,answer:`la semaine précédente`,accept:[`la semaine d'avant`],wrong:[`la semaine dernière`,`la semaine suivante`,`la semaine prochaine`,`cette semaine-là`],en:`When I ran into her last year, she told me she had resigned the week before.`,why:`La semaine dernière becomes la semaine précédente.`},{id:`dans-deux-jours`,fr:`Il m'avait promis qu'il me rembourserait ____, mais je n'ai jamais revu mon argent.`,cue:`(dans deux jours)`,answer:`deux jours plus tard`,accept:[`deux jours après`,`le surlendemain`],wrong:[`dans deux jours`,`deux jours plus tôt`,`deux jours avant`,`le lendemain`],en:`He had promised to pay me back two days later, but I never saw my money again.`,why:`Dans deux jours becomes deux jours plus tard.`}]},{id:`concordance-des-temps`,title:`Fais la concordance des temps`,en:`Apply the sequence of tenses`,level:4,items:[{id:`present-imparfait`,fr:`Quand je l'ai appelée, elle m'a dit qu'elle ____ en réunion et qu'elle me rappellerait.`,cue:`(être)`,answer:`était`,wrong:[`est`,`serait`,`a été`,`sera`],en:`When I called her, she told me she was in a meeting and would call me back.`,why:`Présent → imparfait after a past reporting verb.`},{id:`croire-imparfait`,fr:`Je croyais que tu ____ couramment le russe !`,cue:`(parler)`,answer:`parlais`,wrong:[`parles`,`parlait`,`avais parlé`],en:`I thought you spoke fluent Russian!`,why:`After a past verb (je croyais), the present becomes imparfait.`},{id:`depuis-imparfait`,fr:`Quand je l'ai rencontré en 2015, il m'a dit qu'il ____ ce poste depuis trois ans.`,cue:`(occuper)`,answer:`occupait`,wrong:[`occupe`,`occuperait`,`a occupé`,`occupera`],en:`When I met him in 2015, he told me he had held that position for three years.`,why:`Présent + depuis → imparfait + depuis after a past verb.`},{id:`falloir-imparfait`,fr:`Ma mère m'avait dit qu'il ____ que je rappelle ma tante, mais j'ai complètement oublié.`,cue:`(falloir)`,answer:`fallait`,accept:[`faudrait`],wrong:[`faut`,`faille`,`a fallu`],en:`My mother had told me I needed to call my aunt back, but I completely forgot.`,why:`Il faut → il fallait; the subjunctive after it stays as it is.`},{id:`pc-pqp-temoin`,fr:`Le témoin a affirmé qu'il ____ l'accusé la veille du crime.`,cue:`(voir)`,answer:`avait vu`,wrong:[`a vu`,`voyait`,`aurait vu`,`vit`],en:`The witness stated that he had seen the defendant the day before the crime.`,why:`Passé composé → plus-que-parfait after a past reporting verb.`},{id:`pqp-postuler`,fr:`Elle m'a expliqué qu'elle ____ déjà postulé l'année précédente.`,cue:`(avoir)`,answer:`avait`,wrong:[`a`,`aurait`,`aura`,`ait`],en:`She explained that she had already applied the previous year.`,why:`A past action before the moment of speaking → plus-que-parfait.`},{id:`se-demander-pqp`,fr:`Je me demandais si tu ____ mon message.`,cue:`(recevoir)`,answer:`avais reçu`,wrong:[`as reçu`,`aies reçu`,`auras reçu`],en:`I was wondering whether you had got my message.`,why:`Passé composé → plus-que-parfait after a past verb (je me demandais).`},{id:`savoir-pqp`,fr:`Personne ne savait que le directeur ____ sa démission la veille.`,cue:`(donner)`,answer:`avait donné`,wrong:[`a donné`,`donnait`,`ait donné`,`aura donné`],en:`Nobody knew the director had handed in his resignation the day before.`,why:`An action before the past moment → plus-que-parfait.`},{id:`futur-cond-impots`,fr:`Le gouvernement avait promis que les impôts ____ pas, et ils ont augmenté.`,cue:`(augmenter)`,answer:`n'augmenteraient`,wrong:[`n'augmenteront`,`n'augmentent`,`n'augmenterait`,`n'augmentèrent`],en:`The government had promised that taxes wouldn't go up, and they did.`,why:`Futur → conditionnel présent: the future seen from the past.`},{id:`jurer-cond`,fr:`Il m'avait juré qu'il ne ____ plus jamais, et il a recommencé le lendemain.`,cue:`(recommencer)`,answer:`recommencerait`,accept:[`recommençait`],wrong:[`recommencera`,`recommence`,`recommencerais`],en:`He had sworn to me he would never do it again, and he did it again the next day.`,why:`Futur → conditionnel présent after a past verb (il avait juré).`},{id:`prevoir-cond`,fr:`Les météorologues avaient prévu qu'il ____ toute la semaine ; ils se sont trompés.`,cue:`(pleuvoir)`,answer:`pleuvrait`,wrong:[`pleuvra`,`pleuvait`,`pleuve`,`aurait plu`],en:`The forecasters had predicted it would rain all week; they were wrong.`,why:`Futur → conditionnel présent: still to come at the time.`},{id:`esperer-cond`,fr:`J'espérais que tu ____ venir à mon anniversaire samedi dernier.`,cue:`(pouvoir)`,answer:`pourrais`,accept:[`pouvais`],wrong:[`pourras`,`puisses`,`pourrait`,`peux`],en:`I was hoping you'd be able to come to my birthday party last Saturday.`,why:`Futur → conditionnel after a past verb (j'espérais).`},{id:`demander-si-cond`,fr:`Elle m'avait demandé si ____ là pour son anniversaire, mais j'ai dû annuler.`,cue:`(être)`,answer:`je serais`,accept:[`j'étais`],wrong:[`je serai`,`je sois`,`je serait`,`je suis`],en:`She had asked me whether I'd be there for her birthday, but I had to cancel.`,why:`Futur → conditionnel présent after a past verb (elle m'avait demandé).`},{id:`futur-proche`,fr:`En juin, mes voisins m'avaient annoncé qu'ils ____ déménager à la rentrée ; ils sont toujours là.`,cue:`(aller)`,answer:`allaient`,wrong:[`vont`,`iraient`,`sont allés`,`allèrent`],en:`In June, my neighbours had told me they were going to move in September; they're still here.`,why:`Futur proche (ils vont) → aller in the imparfait (ils allaient) + infinitive.`},{id:`passe-recent`,fr:`À mon arrivée, on m'a dit que le dernier train ____ partir.`,cue:`(venir de)`,answer:`venait de`,wrong:[`vient de`,`était venu de`,`viendrait de`,`venait`],en:`When I arrived, I was told the last train had just left.`,why:`Passé récent (vient de) → venir in the imparfait (venait de) + infinitive.`},{id:`futur-anterieur-plombier`,fr:`Le plombier m'avait assuré qu'il ____ avant midi, mais il est arrivé à 15 h.`,cue:`(terminer)`,answer:`aurait terminé`,accept:[`terminerait`],wrong:[`aura terminé`,`terminera`,`termine`,`aurait terminer`],en:`The plumber had assured me he would have finished by noon, but he turned up at 3 pm.`,why:`Futur antérieur (il aura terminé) → conditionnel passé (il aurait terminé).`},{id:`futur-anterieur-travaux`,fr:`Le maire avait assuré que, d'ici la rentrée, l'entreprise ____ fini les travaux ; ils ont duré jusqu'en mars.`,cue:`(avoir)`,answer:`aurait`,wrong:[`aura`,`avait`,`aurais`,`ait`],en:`The mayor had promised that by September the company would have finished the work; it went on until March.`,why:`Futur antérieur (aura fini) → conditionnel passé (aurait fini) after a past verb.`},{id:`imparfait-reste`,fr:`Il m'a raconté qu'à l'époque, il ____ dans une colocation à Berlin.`,cue:`(vivre)`,answer:`vivait`,accept:[`avait vécu`],wrong:[`vivrait`,`a vécu`,`vit`,`vivra`],en:`He told me that back then he lived in a flatshare in Berlin.`,why:`The imparfait doesn't change after a past reporting verb.`},{id:`imparfait-a-lepoque`,fr:`Je ne savais pas que vous ____ ensemble à l'époque.`,cue:`(être)`,answer:`étiez`,accept:[`aviez été`],wrong:[`êtes`,`seriez`,`soyez`],en:`I didn't know you two were together back then.`,why:`A past main verb (je ne savais pas) and a past state: imparfait.`},{id:`conditionnel-reste`,fr:`Il m'a dit qu'il ____ volontiers, mais qu'il était pris ce soir-là.`,cue:`(venir)`,answer:`viendrait`,accept:[`serait venu`],wrong:[`viendra`,`vient`,`venait`,`viendrai`],en:`He told me he'd gladly come, but he was busy that evening.`,why:`The conditionnel doesn't change after a past reporting verb.`},{id:`present-pas-de-changement`,fr:`Le patron dit toujours qu'il ____ confiance en nous.`,cue:`(avoir)`,answer:`a`,wrong:[`avait`,`aurait`,`ait`,`aura`],en:`The boss always says he trusts us.`,why:`The reporting verb is in the present: no change of tense.`},{id:`verite-generale`,fr:`Notre prof de chimie nous a rappelé que l'eau ____ à 100 degrés.`,cue:`(bouillir)`,answer:`bout`,accept:[`bouillait`],wrong:[`bouillira`,`bouille`,`bouillirait`,`bouillit`],en:`Our chemistry teacher reminded us that water boils at 100 degrees.`,why:`A general truth can stay in the present, even after a past verb.`}]},{id:`interrogation-indirecte`,title:`Complète la question indirecte`,en:`Complete the indirect question`,level:4,items:[{id:`si-oui-non`,fr:`Je voudrais savoir ____ la banque a bien reçu mon dossier.`,answer:`si`,wrong:[`est-ce que`,`qu'est-ce que`,`ce que`,`que`],en:`I would like to know whether the bank actually received my file.`,why:`A yes/no question becomes si (never est-ce que).`},{id:`s-il-futur`,fr:`Mon frère est débordé ; je ne sais pas ____ pourra se libérer samedi.`,answer:`s'il`,wrong:[`est-ce qu'il`,`qu'il`,`ce qu'il`],en:`My brother is swamped; I don't know if he'll be able to get away on Saturday.`,why:`Si becomes s' before il; in an indirect question, si can take the future.`},{id:`si-cond`,fr:`Elle m'a demandé si nous ____ à la réunion du lendemain.`,cue:`(assister)`,answer:`assisterions`,accept:[`assistions`],wrong:[`assisterons`,`assistons`,`assisterions-nous`],en:`She asked me whether we would attend the following day's meeting.`,why:`Si + conditionnel: the future seen from the past (after elle m'a demandé).`},{id:`ce-que-penser`,fr:`Dis-moi franchement ____ tu penses de mon texte.`,answer:`ce que`,wrong:[`qu'est-ce que`,`quoi`,`que`,`ce qui`],en:`Tell me honestly what you think of my text.`,why:`Qu'est-ce que becomes ce que in an indirect question.`},{id:`ce-que-vouloir-dire`,fr:`Personne n'a compris ____ a voulu dire par là.`,answer:`ce qu'il`,wrong:[`qu'est-ce qu'il`,`ce qui`,`quoi il`,`qu'il`],en:`Nobody understood what he meant by that.`,why:`Qu'est-ce que becomes ce que (ce qu' before il).`},{id:`ce-qui-prendre`,fr:`Il est parti en claquant la porte ; je me demande bien ____ lui a pris.`,answer:`ce qui`,accept:[`ce qu'il`],wrong:[`qu'est-ce qui`,`quoi`,`qui`],en:`He stormed out, slamming the door; I really wonder what got into him.`,why:`Qu'est-ce qui becomes ce qui in an indirect question.`},{id:`a-quoi`,fr:`Je ne vois pas du tout ____ tu fais allusion.`,answer:`à quoi`,wrong:[`de quoi`,`ce que`,`qu'est-ce que`,`à ce que`],en:`I really don't see what you're getting at.`,why:`After a preposition, quoi stays: faire allusion à → à quoi.`},{id:`de-quoi`,fr:`Je me demande ____ les deux ministres ont bien pu parler pendant trois heures.`,answer:`de quoi`,accept:[`ce dont`],wrong:[`ce que`,`quoi`,`qu'est-ce que`,`dont`],en:`I wonder what on earth the two ministers could have talked about for three hours.`,why:`Parler de → de quoi (or ce dont): the preposition comes first.`},{id:`quoi-infinitif`,fr:`Face à une telle injustice, je ne savais plus ____ dire.`,answer:`quoi`,accept:[`que`],wrong:[`ce que`,`qu'est-ce que`,`ce qui`],en:`Faced with such injustice, I no longer knew what to say.`,why:`Before an infinitive, use quoi (or que), never ce que.`},{id:`qui-sujet`,fr:`On ne sait toujours pas ____ a divulgué l'information à la presse.`,answer:`qui`,wrong:[`qui est-ce qui`,`ce qui`,`qu'est-ce qui`,`quoi`],en:`We still do not know who leaked the information to the press.`,why:`Qui stays qui; qui est-ce qui belongs to direct questions.`},{id:`ou-pouvoir`,fr:`Pourriez-vous me dire où ____ garer ma voiture ?`,answer:`je peux`,accept:[`je pourrais`],wrong:[`est-ce que je peux`,`puis-je`,`peux-je`,`que je peux`],en:`Could you tell me where I can park my car?`,why:`No inversion and no est-ce que after où in an indirect question.`},{id:`quand-ordre`,fr:`J'attends mes résultats : savez-vous quand ____ publiés ?`,answer:`ils seront`,wrong:[`seront-ils`,`est-ce qu'ils seront`,`qu'ils seront`],en:`I'm waiting for my results: do you know when they'll be published?`,why:`Statement order (ils seront): no inversion, no est-ce que.`},{id:`pourquoi-present`,fr:`J'aimerais comprendre pourquoi ____ toujours en retard.`,answer:`tu es`,wrong:[`es-tu`,`est-ce que tu es`,`tu sois`],en:`I'd like to understand why you're always late.`,why:`After pourquoi in an indirect question: subject + verb, no est-ce que.`},{id:`pourquoi-passe`,fr:`Ses parents lui ont demandé pourquoi ____ si tard.`,cue:`(« Pourquoi es-tu rentré si tard ? »)`,answer:`il était rentré`,wrong:[`était-il rentré`,`est-ce qu'il était rentré`,`es-tu rentré`],en:`His parents asked him why he had come home so late.`,why:`No inversion; after a past verb, the passé composé becomes plus-que-parfait.`},{id:`comment-pouvoir`,fr:`Je ne comprends pas comment ____ se tromper à ce point.`,cue:`(pouvoir)`,answer:`ils ont pu`,wrong:[`ont-ils pu`,`est-ce qu'ils ont pu`,`qu'ils ont pu`,`ils aient pu`],en:`I don't understand how they could have got it so wrong.`,why:`Indirect question: subject before verb, indicative, no est-ce que.`},{id:`combien-vouloir`,fr:`Le vendeur m'a demandé combien ____ mettre.`,cue:`(vouloir)`,answer:`je voulais`,wrong:[`voulais-je`,`est-ce que je voulais`,`vous voulez`,`voulez-vous`],en:`The salesman asked me how much I wanted to spend.`,why:`Statement order (je voulais), with the person and the tense shifted.`},{id:`combien-de-temps`,fr:`Tu sais combien de temps ____ pour aller à Nantes en train ?`,answer:`il faut`,wrong:[`faut-il`,`est-ce qu'il faut`,`qu'il faut`],en:`Do you know how long it takes to get to Nantes by train?`,why:`Even inside a question, the indirect question keeps statement order: il faut.`},{id:`ou-mettre`,fr:`Je me suis demandé où ____ mes clés.`,cue:`(mettre)`,answer:`j'avais mis`,wrong:[`avais-je mis`,`est-ce que j'avais mis`,`j'avais mises`],en:`I wondered where I had put my keys.`,why:`Statement order after où; plus-que-parfait after a past verb.`},{id:`lequel-choisir`,fr:`Il y a trois forfaits ; je n'arrive pas à décider ____ choisir.`,answer:`lequel`,wrong:[`quel`,`laquelle`,`qu'est-ce que`,`lesquelles`],en:`There are three plans; I can't decide which one to choose.`,why:`Lequel (un forfait, masculine) stands alone; quel needs a noun.`},{id:`quel-etre`,fr:`Je ne sais plus ____ était le nom de cet hôtel.`,answer:`quel`,wrong:[`lequel`,`qu'est-ce qui`,`ce qui`,`quoi`],en:`I can't remember what the name of that hotel was.`,why:`Quel agrees with le nom and stays the same in an indirect question.`}]}],n=[{id:`voix-passive`,title:`Complète avec le passif ou une tournure équivalente`,en:`Complete with the passive or an equivalent structure`,level:3,items:[{id:`pont-construit`,fr:`Le nouveau pont ____ en moins de deux ans.`,cue:`(construire, passé composé)`,answer:`a été construit`,wrong:[`a construit`,`est construit`,`a été construite`,`était construit`],en:`The new bridge was built in less than two years.`,why:`Passive passé composé: a été + participle, agreeing with the subject (le pont, masculine).`},{id:`resultats-publies`,fr:`Les résultats de l'enquête ____ demain matin.`,cue:`(publier, futur)`,answer:`seront publiés`,wrong:[`publieront`,`seront publiées`,`sera publié`,`vont être publié`],en:`The results of the investigation will be published tomorrow morning.`,why:`Future passive: seront + participle; publiés agrees with les résultats (masculine plural).`},{id:`places-reservees`,fr:`Toutes les places ____ bien avant notre arrivée.`,cue:`(réserver, plus-que-parfait)`,answer:`avaient été réservées`,wrong:[`avaient réservé`,`avaient été réservés`,`étaient réservées`,`ont été réservées`],en:`All the seats had been booked well before we arrived.`,why:`Plus-que-parfait passive: avaient été + participle, feminine plural like les places.`},{id:`dossier-valide`,fr:`Il faut que le dossier ____ avant vendredi.`,cue:`(valider, subjonctif présent)`,answer:`soit validé`,wrong:[`est validé`,`soit validée`,`sera validé`,`valide`],en:`The file has to be approved before Friday.`,why:`Il faut que takes the subjunctive: soit + participle, masculine like le dossier.`},{id:`exposition-visitee`,fr:`Cette exposition ____ par plus de 200 000 personnes l'été dernier.`,cue:`(visiter, passé composé)`,answer:`a été visitée`,wrong:[`a visité`,`a été visité`,`est visitée`,`s'est visitée`],en:`This exhibition was visited by more than 200,000 people last summer.`,why:`Passé composé passive: a été + participle; visitée agrees with l'exposition (feminine).`},{id:`immeuble-detruit`,fr:`Sans l'intervention rapide des pompiers, l'immeuble ____ par les flammes.`,cue:`(détruire, conditionnel passé)`,answer:`aurait été détruit`,wrong:[`aurait détruit`,`serait détruit`,`aurait été détruite`,`avait été détruit`],en:`Without the firefighters' quick response, the building would have been destroyed by the flames.`,why:`Past conditional passive: aurait été + participle; détruit agrees with l'immeuble (masculine).`},{id:`velos-voles`,fr:`Chaque année, des milliers de vélos ____ dans les grandes villes.`,cue:`(voler, présent)`,answer:`sont volés`,wrong:[`volent`,`sont volées`,`est volé`,`ont volé`],en:`Every year, thousands of bikes are stolen in big cities.`,why:`Present passive: sont + participle, agreeing with les vélos (masculine plural).`},{id:`reforme-adoptee`,fr:`D'ici juin, la réforme ____ par le Parlement.`,cue:`(adopter, futur antérieur)`,answer:`aura été adoptée`,wrong:[`aura adopté`,`sera adoptée`,`aura été adopté`,`aurait été adoptée`],en:`By June, the reform will have been passed by Parliament.`,why:`Futur antérieur passive: aura été + participle, feminine like la réforme.`},{id:`admise-sciences-po`,fr:`Elle ____ à Sciences Po, mais elle a préféré partir étudier à Montréal.`,cue:`(admettre, plus-que-parfait)`,answer:`avait été admise`,wrong:[`avait admis`,`avait été admis`,`était admise`,`s'était admise`],en:`She had been accepted at Sciences Po, but she chose to go and study in Montreal instead.`,why:`Plus-que-parfait passive: avait été + participle; admise agrees with elle.`},{id:`joueuses-selectionnees`,fr:`Les deux joueuses ont ____ pour la finale.`,cue:`(sélectionner)`,answer:`été sélectionnées`,wrong:[`sélectionnées`,`été sélectionnés`,`étées sélectionnées`,`étés sélectionnées`],en:`Both players have been selected for the final.`,why:`Été never agrees; the participle after it agrees with the subject (les joueuses, feminine plural).`},{id:`femmes-exclues`,fr:`Au XIXe siècle, les femmes ____ de la plupart des universités.`,cue:`(exclure, imparfait)`,answer:`étaient exclues`,wrong:[`excluaient`,`étaient exclus`,`étaient excluées`,`ont été exclues`],en:`In the 19th century, women were excluded from most universities.`,why:`Imparfait passive: étaient + participle; exclu becomes exclue(s), never 'excluée'.`},{id:`decision-approuvee`,fr:`Cette décision devra ____ par l'ensemble des actionnaires.`,cue:`(approuver)`,answer:`être approuvée`,wrong:[`approuver`,`être approuvé`,`été approuvée`,`avoir approuvé`],en:`This decision will have to be approved by all the shareholders.`,why:`After devoir, the passive infinitive is être + participle; approuvée agrees with la décision.`},{id:`couvert-de-neige`,fr:`Le sommet est couvert ____ neige toute l'année.`,answer:`de`,wrong:[`par`,`avec`,`en`],en:`The summit is covered in snow all year round.`,why:`Verbs describing a state (couvert, entouré, rempli) take de, with no article after it.`},{id:`remplie-de-touristes`,fr:`Pendant le festival, la vieille ville est remplie ____ touristes du matin au soir.`,answer:`de`,wrong:[`par`,`avec`,`à`],en:`During the festival, the old town is packed with tourists from morning till night.`,why:`Rempli de describes a state, so the complement takes de and drops the article.`},{id:`interpelle-par`,fr:`Le suspect a été interpellé ____ deux policiers en civil.`,answer:`par`,wrong:[`de`,`des`,`à`],en:`The suspect was arrested by two plain-clothes police officers.`,why:`An agent carrying out a concrete action is introduced by par.`},{id:`se-faire-voler`,fr:`Il ____ son portefeuille dans le métro.`,cue:`(se faire voler, passé composé)`,answer:`s'est fait voler`,wrong:[`a été volé`,`s'est fait volé`,`est fait voler`,`s'est faite voler`],en:`He had his wallet stolen on the metro.`,why:`Se faire + infinitive for something that happens to someone: voler stays an infinitive and fait never agrees.`},{id:`se-faire-rembourser`,fr:`Nous ____ nos billets sans aucune difficulté.`,cue:`(se faire rembourser, passé composé)`,answer:`nous sommes fait rembourser`,wrong:[`avons été remboursés`,`nous sommes faits rembourser`,`nous sommes fait remboursés`,`sommes fait rembourser`],en:`We got our tickets refunded without any difficulty.`,why:`Se faire + infinitive takes être, and fait stays invariable when an infinitive follows.`},{id:`vin-se-boit`,fr:`Ce vin blanc ____ frais, entre 8 et 10 degrés.`,cue:`(se boire)`,answer:`se boit`,wrong:[`boit`,`se boivent`,`se bois`],en:`This white wine is drunk chilled, between 8 and 10 degrees.`,why:`The pronominal passive (se + verb) says how something is usually done; it agrees with ce vin.`},{id:`ne-se-fait-pas`,fr:`Ce genre de remarque ne ____ pas en entretien d'embauche.`,cue:`(se faire)`,answer:`se fait`,wrong:[`fait`,`se font`,`se faites`],en:`That kind of remark just isn't made in a job interview.`,why:`Ça ne se fait pas: the pronominal passive for social norms, singular to agree with ce genre.`},{id:`mot-s-emploie`,fr:`Ce mot ____ surtout à l'écrit.`,cue:`(s'employer)`,answer:`s'emploie`,wrong:[`emploie`,`s'employe`,`s'emploient`],en:`This word is used mostly in writing.`,why:`Pronominal passive of employer; -oyer verbs change y to i before a silent e.`},{id:`on-m-a-demande`,fr:`À l'accueil, ____ de patienter quelques minutes.`,answer:`on m'a demandé`,wrong:[`j'ai été demandé`,`je suis demandé`,`je me suis demandé`],en:`At reception, I was asked to wait a few minutes.`,why:`Demander à quelqu'un: the person is an indirect object, so there is no passive. Use on.`},{id:`on-lui-a-propose`,fr:`L'an dernier, ____ un poste à Montréal, mais il l'a refusé.`,answer:`on lui a proposé`,accept:[`il s'est vu proposer`],wrong:[`il a été proposé`,`on l'a proposé`,`il s'est proposé`],en:`Last year he was offered a job in Montreal, but he turned it down.`,why:`Proposer quelque chose à quelqu'un: the person is an indirect object, so French uses on, not the passive.`}]},{id:`gerondif-participe`,title:`Complète avec le gérondif, le participe ou l'adjectif`,en:`Complete with the gerund, the participle or the adjective`,level:3,items:[{id:`en-voyageant`,fr:`C'est ____ qu'on progresse le plus vite en langues.`,cue:`(voyager)`,answer:`en voyageant`,wrong:[`en voyagant`,`voyageant`,`en voyagé`],en:`It's by travelling that you make the fastest progress in languages.`,why:`Gérondif of means: en + -ant; -ger verbs keep the e before a (voyageant).`},{id:`en-glissant`,fr:`Il s'est cassé le poignet ____ sur le verglas.`,cue:`(glisser)`,answer:`en glissant`,wrong:[`glissant`,`en glissé`,`en glissent`],en:`He broke his wrist slipping on the ice.`,why:`The gérondif gives the circumstances of the main action and shares its subject.`},{id:`en-partant`,fr:`Vous éviterez les embouteillages ____ avant 7 heures.`,cue:`(partir)`,answer:`en partant`,wrong:[`partant`,`en partir`,`en parti`],en:`You'll avoid the traffic jams if you leave before 7.`,why:`Gérondif of condition: en partant = si vous partez.`},{id:`en-conduisant`,fr:`Il ne faut jamais téléphoner ____.`,cue:`(conduire)`,answer:`en conduisant`,wrong:[`conduisant`,`en conduiant`,`en conduire`],en:`You should never make phone calls while driving.`,why:`Simultaneity with the same subject: en + -ant, built on nous conduisons.`},{id:`tout-en-remerciant`,fr:`Elle a décliné l'offre, tout ____ chaleureusement le recruteur.`,cue:`(remercier)`,answer:`en remerciant`,wrong:[`remerciant`,`en remercier`,`en remercié`],en:`She turned down the offer, while warmly thanking the recruiter.`,why:`Tout en + gérondif links two simultaneous actions that contrast.`},{id:`sachant-parler`,fr:`Les personnes ____ parler espagnol sont priées de se signaler.`,cue:`(savoir)`,answer:`sachant`,wrong:[`savant`,`en sachant`,`sachantes`],en:`Anyone who can speak Spanish is asked to come forward.`,why:`The participe présent replaces qui + verb; savoir has the irregular form sachant, which never agrees.`},{id:`ayant-reussi`,fr:`Les candidats ____ l'épreuve écrite passeront un oral en juin.`,cue:`(réussir)`,answer:`ayant réussi`,wrong:[`ayant réussis`,`étant réussi`,`en ayant réussi`,`réussis`],en:`Candidates who have passed the written exam will take an oral in June.`,why:`Ayant + participle marks an action completed before the main one; with avoir it never agrees.`},{id:`etant-souffrante`,fr:`La ministre, ____ souffrante, a annulé tous ses déplacements.`,cue:`(être)`,answer:`étant`,wrong:[`étante`,`été`,`ayant`],en:`The minister, being unwell, cancelled all her trips.`,why:`Étant gives a cause in written French; as a participle it never agrees.`},{id:`ayant-perdu`,fr:`Le voyageur, ____ perdu son passeport, n'a pas pu embarquer.`,answer:`ayant`,wrong:[`étant`,`aillant`,`ayants`],en:`The traveller, having lost his passport, couldn't board.`,why:`Compound participle with avoir (ayant + participle) for an earlier action; perdre takes avoir.`},{id:`etant-arrivee`,fr:`Ma collègue, ____ en retard, a raté le début de la conférence.`,cue:`(arriver)`,answer:`étant arrivée`,wrong:[`ayant arrivée`,`étant arrivé`,`ayant arrivé`],en:`My colleague, having arrived late, missed the start of the lecture.`,why:`Être verbs form the compound participle with étant, and the participle agrees: étant arrivée.`},{id:`fatigant`,fr:`Ce trajet quotidien est vraiment ____.`,cue:`(fatiguer)`,answer:`fatigant`,wrong:[`fatiguant`,`fatigante`,`fatigants`],en:`This daily commute is really tiring.`,why:`The adjective is fatigant (no u), agreeing with ce trajet; fatiguant is the participle.`},{id:`convaincants`,fr:`Ses arguments n'étaient pas très ____.`,cue:`(convaincre)`,answer:`convaincants`,wrong:[`convainquants`,`convaincant`,`convainquant`,`convaincantes`],en:`His arguments weren't very convincing.`,why:`The adjective convaincant agrees (des arguments convaincants); the participle convainquant keeps -qu-.`},{id:`en-convainquant`,fr:`L'avocate a obtenu l'acquittement en ____ le jury de la bonne foi de son client.`,cue:`(convaincre)`,answer:`convainquant`,wrong:[`convaincant`,`convaincu`,`convainquent`],en:`The lawyer secured an acquittal by convincing the jury of her client's good faith.`,why:`After en it is the gérondif, built on the verb: convainquant, with -qu-.`},{id:`precedant`,fr:`Les jours ____ l'élection ont été particulièrement tendus.`,cue:`(précéder)`,answer:`précédant`,wrong:[`précédent`,`précédents`,`précédants`],en:`The days leading up to the election were particularly tense.`,why:`It has an object (l'élection), so it is the participle précédant, invariable.`},{id:`precedent`,fr:`Comme je le disais dans mon message ____, la réunion est reportée.`,cue:`(précéder)`,answer:`précédent`,wrong:[`précédant`,`précédente`,`précédents`],en:`As I said in my previous message, the meeting has been postponed.`,why:`No object: it is the adjective précédent, agreeing with message (masculine singular).`},{id:`differents`,fr:`Nos points de vue sont très ____ sur ce sujet.`,cue:`(différer)`,answer:`différents`,wrong:[`différants`,`différant`,`différentes`],en:`Our points of view are very different on this subject.`,why:`After être it is the adjective différent, agreeing with points de vue (masculine plural).`},{id:`differant`,fr:`Les avis ____ sur ce point, la décision a été reportée.`,cue:`(différer)`,answer:`différant`,wrong:[`différents`,`différent`,`différants`],en:`As opinions differed on this point, the decision was postponed.`,why:`A participle clause with its own subject needs the verb form différant, which is invariable.`},{id:`negligent`,fr:`Ce serveur est vraiment ____ : il oublie la moitié des commandes.`,cue:`(négliger)`,answer:`négligent`,wrong:[`négligeant`,`négligente`,`négligeants`],en:`This waiter is really careless: he forgets half the orders.`,why:`The adjective is négligent (-ent); négligeant is the participle.`},{id:`negligeant`,fr:`Le maire, ____ ses responsabilités, a laissé la situation se dégrader.`,cue:`(négliger)`,answer:`négligeant`,accept:[`en négligeant`],wrong:[`négligent`,`négligeants`,`négligente`],en:`The mayor, neglecting his responsibilities, let the situation deteriorate.`,why:`With a direct object (ses responsabilités) it is the participle négligeant, invariable.`},{id:`provocante`,fr:`Elle portait une tenue jugée trop ____ par la direction.`,cue:`(provoquer)`,answer:`provocante`,wrong:[`provoquante`,`provocant`,`provoquant`],en:`She was wearing an outfit the management considered too provocative.`,why:`The adjective is provocant, here feminine (une tenue); provoquant is the participle.`},{id:`en-provoquant`,fr:`Le ministre a mis le feu aux poudres ____ les syndicats.`,cue:`(provoquer)`,answer:`en provoquant`,wrong:[`en provocant`,`provocant`,`en provoqué`],en:`The minister stirred things up by provoking the unions.`,why:`Gérondif of means, built on the verb: en provoquant (-qu-); provocant is the adjective.`},{id:`encourageants`,fr:`Ce sont des résultats très ____ pour l'équipe.`,cue:`(encourager)`,answer:`encourageants`,wrong:[`encourageant`,`encourageantes`,`encouragés`],en:`These are very encouraging results for the team.`,why:`Used as an adjective, the -ant form agrees: des résultats encourageants.`}]},{id:`infinitif-passe`,title:`Complète avec l'infinitif présent ou passé`,en:`Complete with the present or past infinitive`,level:4,items:[{id:`apres-avoir-lu`,fr:`Après ____ le contrat, elle a appelé son avocat.`,cue:`(lire)`,answer:`avoir lu`,wrong:[`lire`,`avoir lue`,`être lu`,`avoir lit`],en:`After reading the contract, she called her lawyer.`,why:`Après is followed by the past infinitive: avoir + participle, with no agreement with the subject.`},{id:`apres-etre-rentres`,fr:`Après ____ de vacances, ils ont décidé de déménager.`,cue:`(rentrer)`,answer:`être rentrés`,wrong:[`avoir rentré`,`être rentré`,`rentrer`,`avoir rentrés`],en:`After getting back from holiday, they decided to move house.`,why:`Rentrer takes être, so the participle agrees with the subject ils: être rentrés.`},{id:`apres-etre-partie`,fr:`Après ____ à la retraite, ma mère s'est mise au piano.`,cue:`(partir)`,answer:`être partie`,wrong:[`avoir parti`,`être parti`,`partir`,`s'être partie`],en:`After retiring, my mother took up the piano.`,why:`Partir takes être; the participle agrees with ma mère: être partie.`},{id:`apres-s-etre-levee`,fr:`Après ____ tôt, Claire a pu boucler son rapport avant midi.`,cue:`(se lever)`,answer:`s'être levée`,wrong:[`se lever`,`avoir levé`,`s'être levé`,`être levée`],en:`Having got up early, Claire was able to finish her report before noon.`,why:`Pronominal verbs take être: s'être + participle, agreeing with Claire.`},{id:`nous-etre-retrouves`,fr:`Après ____ au café, nous avons parlé jusqu'à minuit.`,cue:`(se retrouver)`,answer:`nous être retrouvés`,wrong:[`s'être retrouvés`,`nous avoir retrouvés`,`se retrouver`,`nous être retrouvé`],en:`After meeting up at the café, we talked until midnight.`,why:`The reflexive pronoun matches the subject (nous être), and the participle agrees: retrouvés.`},{id:`apres-avoir-voyage`,fr:`Après ____ pendant des années, ils se sont enfin installés à Lisbonne.`,cue:`(voyager)`,answer:`avoir voyagé`,wrong:[`voyager`,`être voyagés`,`avoir voyager`,`avoir voyagés`],en:`After travelling for years, they finally settled in Lisbon.`,why:`Après + past infinitive; voyager takes avoir, so no agreement with ils.`},{id:`apres-avoir-appris`,fr:`Après ____ la nouvelle, elles ont immédiatement appelé leurs parents.`,cue:`(apprendre)`,answer:`avoir appris`,wrong:[`avoir apprises`,`être apprises`,`apprendre`,`avoir appri`],en:`After hearing the news, they immediately called their parents.`,why:`Apprendre takes avoir, so the participle does not agree with the subject elles.`},{id:`apres-avoir-vecu`,fr:`Ils se sont mariés après ____ ensemble pendant dix ans.`,cue:`(vivre)`,answer:`avoir vécu`,wrong:[`vivre`,`être vécus`,`avoir vécus`,`avoir vivé`],en:`They got married after living together for ten years.`,why:`Après + past infinitive; vivre takes avoir and its participle is vécu.`},{id:`avoir-ete-examine`,fr:`Après ____ par trois médecins, il a enfin obtenu un diagnostic.`,cue:`(examiner)`,answer:`avoir été examiné`,wrong:[`avoir examiné`,`être examiné`,`été examiné`,`avoir été examinés`],en:`After being examined by three doctors, he finally got a diagnosis.`,why:`Passive past infinitive: avoir été + participle, agreeing with the subject (il).`},{id:`avant-de-signer`,fr:`Lisez attentivement les conditions ____ signer quoi que ce soit.`,answer:`avant de`,wrong:[`après`,`avant`,`après de`,`avant que`],en:`Read the terms carefully before signing anything.`,why:`Avant de + infinitive; après would need a past infinitive, and the logic needs "before".`},{id:`sans-avoir-dit`,fr:`Elle est repartie sans ____ un mot.`,cue:`(dire, infinitif passé)`,answer:`avoir dit`,wrong:[`avoir dite`,`être dit`,`avoir dire`,`été dit`],en:`She left again without having said a word.`,why:`Sans + past infinitive: avoir + participle, which does not agree with the subject.`},{id:`sans-s-etre-excusees`,fr:`Elles sont parties sans ____.`,cue:`(s'excuser, infinitif passé)`,answer:`s'être excusées`,wrong:[`s'être excusé`,`s'avoir excusées`,`avoir excusé`,`s'excusées`],en:`They left without having apologised.`,why:`Pronominal verbs take être: s'être excusées, agreeing with elles.`},{id:`regrette-avoir-ete`,fr:`Je regrette ____ si dur avec toi hier soir.`,cue:`(être)`,answer:`d'avoir été`,wrong:[`d'être`,`d'avoir étée`,`d'être été`],en:`I'm sorry I was so harsh with you last night.`,why:`Hier soir is over: regretter de + past infinitive (d'avoir été).`},{id:`remercie-avoir-participe`,fr:`Je vous remercie ____ à notre enquête la semaine dernière.`,cue:`(participer)`,answer:`d'avoir participé`,wrong:[`de participer`,`d'être participé`,`d'avoir participée`],en:`Thank you for taking part in our survey last week.`,why:`The survey is over: remercier de + past infinitive.`},{id:`fiere-avoir-obtenu`,fr:`Elle est très fière ____ son diplôme avec mention l'an dernier.`,cue:`(obtenir)`,answer:`d'avoir obtenu`,wrong:[`d'obtenir`,`d'avoir obtenue`,`d'être obtenue`],en:`She is very proud of having graduated with honours last year.`,why:`The action is finished (l'an dernier): être fier de + past infinitive.`},{id:`souviens-avoir-signe`,fr:`Je ne me souviens pas ____ ce document.`,cue:`(signer)`,answer:`d'avoir signé`,wrong:[`de signer`,`d'être signé`,`d'avoir signée`],en:`I don't remember signing this document.`,why:`To remember (or not) a past action: se souvenir de + past infinitive.`},{id:`felicitee-avoir-couru`,fr:`On l'a félicitée ____ le marathon en moins de quatre heures.`,cue:`(courir)`,answer:`d'avoir couru`,accept:[`pour avoir couru`],wrong:[`de courir`,`d'être courue`,`d'avoir courue`,`pour courir`],en:`She was congratulated on running the marathon in under four hours.`,why:`Féliciter de (or pour) + past infinitive for an achievement already completed.`},{id:`pour-avoir-divulgue`,fr:`Il a été licencié pour ____ des documents confidentiels.`,cue:`(divulguer)`,answer:`avoir divulgué`,wrong:[`divulguer`,`avoir divulgués`,`être divulgué`,`divulgué`],en:`He was fired for leaking confidential documents.`,why:`Pour giving the reason for a past act takes the past infinitive: pour avoir divulgué.`},{id:`ne-pas-avoir-accepte`,fr:`Il regrette de ____ cette offre d'emploi l'an dernier.`,cue:`(ne pas accepter)`,answer:`ne pas avoir accepté`,accept:[`n'avoir pas accepté`],wrong:[`ne pas accepter`,`n'a pas accepté`,`ne pas avoir acceptée`],en:`He regrets not accepting that job offer last year.`,why:`Both parts of the negation go before the past infinitive: ne pas avoir accepté (formal: n'avoir pas accepté).`},{id:`s-etre-disputees`,fr:`Les deux sœurs se sont réconciliées après ____ pendant des années.`,cue:`(se disputer)`,answer:`s'être disputées`,wrong:[`s'être disputé`,`avoir disputé`,`se disputer`,`être disputées`],en:`The two sisters made up after fighting for years.`,why:`Pronominal verb: s'être + participle, agreeing with les sœurs.`}]},{id:`accord-pp-avance`,title:`Accorde le participe passé`,en:`Make the past participle agree (or not)`,level:4,items:[{id:`lettre-ecrite`,fr:`La lettre que j'ai ____ est restée sans réponse.`,cue:`(écrire)`,answer:`écrite`,wrong:[`écrit`,`écrits`,`écrites`],en:`The letter I wrote went unanswered.`,why:`With avoir, agree with a direct object placed before: que = la lettre (feminine singular).`},{id:`photos-vues`,fr:`Tes photos de vacances ? Je les ai ____ hier soir.`,cue:`(voir)`,answer:`vues`,wrong:[`vu`,`vus`,`vue`],en:`Your holiday photos? I looked at them last night.`,why:`Les (= tes photos, feminine plural) comes before avoir: vues.`},{id:`erreurs-faites`,fr:`Quelles erreurs as-tu ____ dans ce rapport ?`,cue:`(faire)`,answer:`faites`,wrong:[`fait`,`faits`,`faite`],en:`What mistakes did you make in this report?`,why:`Quelles erreurs, the direct object, comes before the verb: faites.`},{id:`pages-lues`,fr:`Combien de pages as-tu ____ ce week-end ?`,cue:`(lire)`,answer:`lues`,wrong:[`lu`,`lus`,`lue`],en:`How many pages did you read this weekend?`,why:`Combien de pages, the direct object, comes first: lues.`},{id:`decisions-prises`,fr:`Les décisions qu'elle a ____ ont surpris tout le monde.`,cue:`(prendre)`,answer:`prises`,wrong:[`pris`,`prise`,`prit`],en:`The decisions she made surprised everyone.`,why:`Que (= les décisions, feminine plural) is a direct object placed before avoir: prises.`},{id:`nous-a-telephone`,fr:`Elle nous a ____ dès son arrivée à l'aéroport.`,cue:`(téléphoner)`,answer:`téléphoné`,wrong:[`téléphonés`,`téléphonée`,`téléphonées`],en:`She phoned us as soon as she got to the airport.`,why:`Téléphoner à quelqu'un: nous is an indirect object, so no agreement.`},{id:`leur-a-plu`,fr:`La pièce ? Elle ne leur a pas du tout ____.`,cue:`(plaire)`,answer:`plu`,wrong:[`plue`,`plus`,`plues`],en:`The play? They didn't like it at all.`,why:`Plaire à quelqu'un: leur is indirect, and with avoir the subject never counts: plu.`},{id:`chaleurs-qu-il-a-fait`,fr:`Tu te souviens des fortes chaleurs qu'il a ____ l'été dernier ?`,cue:`(faire)`,answer:`fait`,wrong:[`faites`,`faits`,`faite`],en:`Do you remember the heatwave we had last summer?`,why:`With the impersonal il (il fait chaud), the participle never agrees.`},{id:`s-est-douchee`,fr:`Après le match, elle s'est ____ en vitesse et elle est repartie.`,cue:`(doucher)`,answer:`douchée`,wrong:[`douché`,`douchés`,`douchées`],en:`After the match, she had a quick shower and left.`,why:`Se is the direct object (she showered herself), so the participle agrees: douchée.`},{id:`s-est-lave-les-mains`,fr:`Elle s'est ____ les mains avant de passer à table.`,cue:`(laver)`,answer:`lavé`,wrong:[`lavée`,`lavées`,`lavés`],en:`She washed her hands before sitting down to eat.`,why:`The direct object (les mains) comes after the verb, so no agreement.`},{id:`se-sont-parle`,fr:`Ils se sont ____ pendant des heures au téléphone.`,cue:`(parler)`,answer:`parlé`,wrong:[`parlés`,`parlées`,`parlée`],en:`They talked on the phone for hours.`,why:`Parler à quelqu'un: se is indirect, so the participle does not agree.`},{id:`se-sont-rencontres`,fr:`Ils se sont ____ lors d'un colloque à Genève.`,cue:`(rencontrer)`,answer:`rencontrés`,wrong:[`rencontré`,`rencontrées`,`rencontrée`],en:`They met at a conference in Geneva.`,why:`Rencontrer quelqu'un: se is the direct object, so agree with ils.`},{id:`s-est-rendu-compte`,fr:`Elle s'est ____ compte trop tard de son erreur.`,cue:`(rendre)`,answer:`rendu`,wrong:[`rendue`,`rendus`,`rendues`],en:`She realised her mistake too late.`,why:`In se rendre compte, compte is the direct object, so rendu never agrees.`},{id:`se-sont-succede`,fr:`Les crises se sont ____ depuis le début de l'année.`,cue:`(succéder)`,answer:`succédé`,wrong:[`succédées`,`succédés`,`succédée`],en:`One crisis has followed another since the start of the year.`,why:`Succéder à quelqu'un: se is indirect, so no agreement.`},{id:`se-sont-serre-la-main`,fr:`Les deux candidates se sont ____ la main après le débat.`,cue:`(serrer)`,answer:`serré`,wrong:[`serrées`,`serrés`,`serrée`],en:`The two candidates shook hands after the debate.`,why:`La main is the direct object and comes after the verb: no agreement.`},{id:`se-sont-offert`,fr:`Elles se sont ____ des livres anciens pour Noël.`,cue:`(offrir)`,answer:`offert`,wrong:[`offertes`,`offerts`,`offerte`],en:`They gave each other antique books for Christmas.`,why:`Offrir à quelqu'un: se is indirect and the object (des livres) comes after, so no agreement.`},{id:`cadeaux-offerts`,fr:`Les cadeaux qu'elles se sont ____ étaient tous faits main.`,cue:`(offrir)`,answer:`offerts`,wrong:[`offert`,`offertes`,`offerte`],en:`The presents they gave each other were all handmade.`,why:`The direct object que (= les cadeaux, masculine plural) comes first: offerts.`},{id:`se-sont-moquees`,fr:`Elles se sont ____ de lui pendant toute la soirée.`,cue:`(se moquer)`,answer:`moquées`,wrong:[`moqué`,`moqués`,`moquée`],en:`They made fun of him all evening.`,why:`Se moquer only exists as a pronominal verb, so it agrees with the subject.`},{id:`s-est-souvenue`,fr:`Ma grand-mère s'est ____ de cette époque avec émotion.`,cue:`(se souvenir)`,answer:`souvenue`,wrong:[`souvenu`,`souvenues`,`souvenus`],en:`My grandmother recalled that time with emotion.`,why:`A pronominal-only verb agrees with its subject (ma grand-mère, feminine).`},{id:`s-est-trompee`,fr:`Elle s'est ____ de numéro trois fois de suite.`,cue:`(se tromper)`,answer:`trompée`,wrong:[`trompé`,`trompés`,`trompées`],en:`She dialled the wrong number three times in a row.`,why:`Se tromper agrees with its subject: elle s'est trompée.`},{id:`s-est-fait-couper`,fr:`Elle s'est ____ couper les cheveux très court.`,cue:`(faire)`,answer:`fait`,wrong:[`faite`,`faits`,`faites`],en:`She had her hair cut very short.`,why:`Fait followed by an infinitive never agrees.`},{id:`les-a-fait-evacuer`,fr:`Les manifestants ? La police les a ____ évacuer en quelques minutes.`,cue:`(faire)`,answer:`fait`,wrong:[`faits`,`faites`,`faite`],en:`The protesters? The police had them removed within minutes.`,why:`Fait + infinitive stays invariable, even with a direct object placed before.`}]}],r=[{id:`relatifs-dont-ou`,title:`Complète avec le bon pronom relatif`,en:`Fill in the right relative pronoun`,level:3,items:[{id:`parler-de`,fr:`C'est le documentaire ____ tout le monde parle en ce moment.`,answer:`dont`,wrong:[`que`,`qui`,`où`,`ce dont`],en:`It's the documentary everyone is talking about at the moment.`,why:`Parler de quelque chose: de + noun becomes dont.`},{id:`avoir-besoin-de`,fr:`Voici le dossier ____ vous aurez besoin pour la réunion de lundi.`,answer:`dont`,wrong:[`que`,`auquel`,`où`,`qui`],en:`Here is the file you'll need for Monday's meeting.`,why:`Avoir besoin de: dont replaces de + noun.`},{id:`se-souvenir-de`,fr:`C'est un détail ____ je ne me souviens plus du tout.`,answer:`dont`,wrong:[`que`,`où`,`auquel`,`qui`],en:`It's a detail I can't remember at all any more.`,why:`Se souvenir de: the de-complement becomes dont.`},{id:`etre-fier-de`,fr:`C'est une réussite ____ toute l'équipe peut être fière.`,answer:`dont`,wrong:[`que`,`laquelle`,`où`,`qui`],en:`It's an achievement the whole team can be proud of.`,why:`Être fier de: dont stands for de + noun.`},{id:`se-plaindre-de`,fr:`C'est un problème ____ les habitants se plaignent depuis des années.`,answer:`dont`,wrong:[`que`,`où`,`auquel`,`qui`],en:`It's a problem residents have been complaining about for years.`,why:`Se plaindre de quelque chose: dont, never que.`},{id:`se-servir-de`,fr:`C'est un outil ____ je me sers tous les jours.`,answer:`dont`,wrong:[`que`,`auquel`,`où`,`lequel`],en:`It's a tool I use every day.`,why:`Se servir de quelque chose: dont.`},{id:`possession-sujet`,fr:`J'ai rencontré une romancière ____ le dernier livre vient d'être adapté au cinéma.`,answer:`dont`,wrong:[`que`,`qui`,`laquelle`,`où`],en:`I met a novelist whose latest book has just been made into a film.`,why:`Possession: le dernier livre de la romancière, so dont.`},{id:`possession-objet`,fr:`C'est un architecte ____ j'admire beaucoup le travail.`,answer:`dont`,wrong:[`que`,`qui`,`auquel`,`où`],en:`He's an architect whose work I greatly admire.`,why:`Le travail de l'architecte: dont, then the normal order (subject, verb, object).`},{id:`dont-inclusion`,fr:`Une vingtaine de personnes ont été évacuées, ____ trois enfants.`,answer:`dont`,accept:[`parmi lesquelles`,`y compris`],wrong:[`que`,`qui`,`où`,`ce dont`],en:`Around twenty people were evacuated, including three children.`,why:`After a number or a group, dont means 'including'.`},{id:`ou-lieu`,fr:`Le quartier ____ j'ai grandi est devenu méconnaissable.`,answer:`où`,accept:[`dans lequel`],wrong:[`dont`,`que`,`qui`,`lequel`],en:`The neighbourhood I grew up in has become unrecognisable.`,why:`Où replaces a place: j'ai grandi dans ce quartier.`},{id:`ou-situation`,fr:`C'est une situation ____ personne ne voudrait se retrouver.`,answer:`où`,accept:[`dans laquelle`],wrong:[`dont`,`que`,`qui`,`laquelle`],en:`It's a situation nobody would want to find themselves in.`,why:`Où also works for a figurative place: se retrouver dans une situation.`},{id:`ou-jour`,fr:`Je me souviens très bien du jour ____ nous avons signé le contrat.`,answer:`où`,wrong:[`quand`,`lequel`,`qui`,`lorsque`],en:`I remember very clearly the day we signed the contract.`,why:`After a noun of time (le jour, le moment), the relative is où, never quand.`},{id:`ou-annee`,fr:`2008, c'est l'année ____ la crise financière a éclaté.`,answer:`où`,wrong:[`quand`,`laquelle`,`lorsque`,`qui`],en:`2008 was the year the financial crisis broke out.`,why:`Où after a noun of time: l'année où.`},{id:`ou-moment`,fr:`Le téléphone a sonné au moment ____ je sortais de la douche.`,answer:`où`,wrong:[`quand`,`lequel`,`lorsque`,`dont`],en:`The phone rang just as I was getting out of the shower.`,why:`Au moment où: où after a noun of time.`},{id:`qui-sujet`,fr:`Les candidats ____ seront retenus recevront un courriel avant vendredi.`,answer:`qui`,wrong:[`que`,`dont`,`où`,`ce qui`],en:`The candidates who are shortlisted will receive an email before Friday.`,why:`Qui is the subject of seront retenus.`},{id:`que-objet-accord`,fr:`Les décisions ____ la direction a prises ne font pas l'unanimité.`,answer:`que`,wrong:[`qui`,`dont`,`où`,`lesquelles`],en:`The decisions the management has taken aren't unanimously supported.`,why:`Que is the direct object of a prises (hence the agreement prises).`},{id:`que-conseiller`,fr:`Le film ____ tu m'as conseillé était vraiment excellent.`,answer:`que`,wrong:[`qui`,`dont`,`où`,`lequel`],en:`The film you recommended to me was really excellent.`,why:`Conseiller quelque chose: a direct object, so que.`},{id:`ce-qui-reprise`,fr:`Il est parti sans dire au revoir, ____ m'a beaucoup vexée.`,answer:`ce qui`,wrong:[`qui`,`ce que`,`quoi`,`ce dont`],en:`He left without saying goodbye, which really upset me.`,why:`Ce qui (subject of a vexée) sums up the whole previous clause.`},{id:`ce-qui-tout`,fr:`Elle s'intéresse à tout ____ touche au design scandinave.`,answer:`ce qui`,wrong:[`ce que`,`qui`,`ce dont`,`que`],en:`She's interested in everything to do with Scandinavian design.`,why:`Ce qui is the subject of touche: tout ce qui = everything that.`},{id:`ce-que-objet`,fr:`Ce n'est pas du tout ____ j'avais imaginé.`,answer:`ce que`,wrong:[`ce qui`,`ce dont`,`que`,`quoi`],en:`It's not at all what I had imagined.`,why:`Ce que: the direct object of imaginer, with no noun before it.`},{id:`ce-dont-besoin`,fr:`C'est exactement ____ nous avions besoin.`,answer:`ce dont`,wrong:[`ce que`,`ce qui`,`dont`,`que`],en:`It's exactly what we needed.`,why:`Avoir besoin de with no noun to refer back to: ce dont.`},{id:`ce-dont-rever`,fr:`Au fond, ____ les soignants rêvent, c'est d'une vraie reconnaissance.`,answer:`ce dont`,wrong:[`ce que`,`ce qui`,`dont`,`ce à quoi`],en:`Deep down, what carers dream of is real recognition.`,why:`Rêver de with no noun before: ce dont (hence the de in c'est d'une).`}]},{id:`relatifs-composes`,title:`Complète avec le bon relatif composé`,en:`Fill in the right compound relative`,level:4,items:[{id:`pour-lesquelles`,fr:`Voici les raisons pour ____ nous avons changé de fournisseur.`,answer:`lesquelles`,wrong:[`lesquels`,`laquelle`,`qui`,`dont`],en:`Here are the reasons why we changed suppliers.`,why:`Pour + lesquelles, agreeing with les raisons (feminine plural).`},{id:`avec-lequel`,fr:`Le logiciel avec ____ nous travaillons a plus de dix ans.`,answer:`lequel`,wrong:[`qui`,`laquelle`,`lesquels`,`dont`],en:`The software we work with is more than ten years old.`,why:`A thing after a preposition: lequel, never qui.`},{id:`sur-lesquels`,fr:`Voici les chiffres sur ____ repose notre analyse.`,answer:`lesquels`,wrong:[`lesquelles`,`qui`,`lequel`,`dont`],en:`Here are the figures our analysis is based on.`,why:`Sur + lesquels, agreeing with les chiffres (masculine plural).`},{id:`dans-lesquelles`,fr:`Les conditions dans ____ travaillent ces ouvriers sont indignes.`,answer:`lesquelles`,wrong:[`lesquels`,`qui`,`laquelle`,`dont`],en:`The conditions these workers work in are appalling.`,why:`Dans + lesquelles, agreeing with les conditions (feminine plural).`},{id:`sans-laquelle`,fr:`C'est une condition sans ____ aucun accord ne sera possible.`,answer:`laquelle`,wrong:[`lequel`,`qui`,`dont`,`lesquelles`],en:`It's a condition without which no agreement will be possible.`,why:`Sans + laquelle (une condition, feminine singular).`},{id:`parmi-lesquels`,fr:`Une dizaine d'experts, parmi ____ deux prix Nobel, ont signé la tribune.`,answer:`lesquels`,wrong:[`qui`,`lesquelles`,`desquels`,`dont`],en:`Around ten experts, including two Nobel laureates, signed the op-ed.`,why:`Parmi always takes lesquels / lesquelles, even for people (never parmi qui).`},{id:`entre-lesquels`,fr:`On m'a proposé deux postes entre ____ j'hésite encore.`,answer:`lesquels`,wrong:[`qui`,`lesquelles`,`lequel`,`dont`],en:`I've been offered two jobs and I'm still torn between them.`,why:`Entre + lesquels (les postes, masculine plural).`},{id:`tenir-a`,fr:`C'est un projet ____ je tiens énormément.`,answer:`auquel`,wrong:[`dont`,`que`,`à lequel`,`duquel`],en:`It's a project I care about enormously.`,why:`Tenir à quelque chose: à + lequel contracts to auquel.`},{id:`repondre-a`,fr:`C'est une question ____ personne n'a su répondre.`,answer:`à laquelle`,wrong:[`dont`,`que`,`auquel`,`laquelle`],en:`It was a question nobody was able to answer.`,why:`Répondre à: à laquelle, agreeing with la question.`},{id:`faire-allusion-a`,fr:`Les incidents ____ vous faites allusion remontent à 2019.`,answer:`auxquels`,wrong:[`dont`,`auxquelles`,`à lesquels`,`que`],en:`The incidents you're referring to date back to 2019.`,why:`Faire allusion à: à + lesquels contracts to auxquels.`},{id:`participer-a`,fr:`Les manifestations ____ elle a participé ont rassemblé des milliers de personnes.`,answer:`auxquelles`,wrong:[`auxquels`,`dont`,`à lesquelles`,`lesquelles`],en:`The demonstrations she took part in drew thousands of people.`,why:`Participer à: auxquelles, agreeing with les manifestations.`},{id:`s-interesser-a`,fr:`Le domaine ____ je m'intéresse le plus, c'est la neurolinguistique.`,answer:`auquel`,wrong:[`dont`,`que`,`à lequel`,`où`],en:`The field I'm most interested in is neurolinguistics.`,why:`S'intéresser à: à + lequel contracts to auquel.`},{id:`grace-a`,fr:`C'est un programme d'échange grâce ____ j'ai pu étudier un an à Séoul.`,answer:`auquel`,wrong:[`duquel`,`dont`,`à lequel`,`lequel`],en:`It's an exchange programme thanks to which I was able to study in Seoul for a year.`,why:`Grâce à + lequel contracts to auquel.`},{id:`pres-de`,fr:`Le parc près ____ nous habitons va être entièrement réaménagé.`,answer:`duquel`,wrong:[`dont`,`de lequel`,`auquel`,`lequel`],en:`The park we live near is going to be completely redesigned.`,why:`Près de + lequel contracts to duquel; dont never follows près.`},{id:`en-face-de`,fr:`L'immeuble en face ____ j'habite est en travaux depuis un an.`,answer:`duquel`,wrong:[`dont`,`auquel`,`de laquelle`,`lequel`],en:`The building opposite my flat has been under renovation for a year.`,why:`En face de + lequel (l'immeuble, masculine): duquel.`},{id:`au-cours-de`,fr:`La réunion au cours ____ le budget a été voté a duré quatre heures.`,answer:`de laquelle`,wrong:[`dont`,`duquel`,`laquelle`,`desquelles`],en:`The meeting during which the budget was voted on lasted four hours.`,why:`Au cours de + laquelle (la réunion): de laquelle, never dont.`},{id:`au-sein-de`,fr:`L'entreprise au sein ____ il a fait toute sa carrière vient d'être rachetée.`,answer:`de laquelle`,wrong:[`dont`,`duquel`,`de qui`,`desquelles`],en:`The company where he spent his whole career has just been bought out.`,why:`Au sein de + laquelle (l'entreprise): de laquelle.`},{id:`a-cause-de`,fr:`Les retards à cause ____ nous avons perdu le contrat étaient évitables.`,answer:`desquels`,wrong:[`dont`,`desquelles`,`duquel`,`de qui`],en:`The delays that cost us the contract could have been avoided.`,why:`À cause de + lesquels (les retards): desquels.`},{id:`a-cote-de-personne`,fr:`La collègue à côté ____ je suis assise au bureau est en congé.`,answer:`de laquelle`,accept:[`de qui`],wrong:[`dont`,`duquel`,`laquelle`,`à laquelle`],en:`The colleague I sit next to at work is on leave.`,why:`À côté de + a person: de laquelle or de qui, never dont.`},{id:`a-qui-personne`,fr:`Le client ____ j'ai envoyé le devis ne m'a toujours pas répondu.`,answer:`à qui`,accept:[`auquel`],wrong:[`dont`,`que`,`qui`,`à lequel`],en:`The client I sent the quote to still hasn't replied.`,why:`Envoyer quelque chose à quelqu'un: à qui or auquel for a person.`},{id:`avec-qui-personne`,fr:`La personne avec ____ je partage mon bureau vient de Montréal.`,answer:`qui`,accept:[`laquelle`],wrong:[`lequel`,`quoi`,`que`,`dont`],en:`The person I share my office with is from Montreal.`,why:`After a preposition, a person takes qui or lequel (here laquelle).`},{id:`ce-a-quoi`,fr:`Le résultat est très loin de ____ nous nous attendions.`,answer:`ce à quoi`,wrong:[`ce que`,`ce dont`,`ce sur quoi`,`ce qui`],en:`The result is a far cry from what we were expecting.`,why:`S'attendre à with ce as the antecedent: ce à quoi.`},{id:`ce-sur-quoi`,fr:`C'est précisément ce sur ____ je voulais insister.`,answer:`quoi`,wrong:[`lequel`,`laquelle`,`que`,`dont`],en:`That's precisely the point I wanted to stress.`,why:`After ce + a preposition, the relative is quoi.`}]},{id:`doubles-pronoms`,title:`Remplace par deux pronoms, dans le bon ordre`,en:`Replace with two pronouns, in the right order`,level:3,items:[{id:`te-le`,fr:`Ton chargeur ? Je ____ rends dès ce soir.`,cue:`(le chargeur, à toi)`,answer:`te le`,wrong:[`le te`,`te lui`,`le toi`,`toi le`],en:`Your charger? I'll give it back to you this evening.`,why:`Me / te / nous / vous come before le / la / les.`},{id:`le-lui`,fr:`Le rapport ? Je ____ transmets demain matin.`,cue:`(le rapport, à la directrice)`,answer:`le lui`,wrong:[`lui le`,`la lui`,`le leur`,`leur le`],en:`The report? I'll pass it on to her tomorrow morning.`,why:`Le / la / les come before lui / leur.`},{id:`nous-les-infinitif`,fr:`Ces chiffres, vous pourriez ____ communiquer avant vendredi ?`,cue:`(ces chiffres, à nous)`,answer:`nous les`,wrong:[`les nous`,`nous leur`,`les leur`,`leur les`],en:`Could you send us these figures before Friday?`,why:`Both pronouns go before the infinitive: nous, then les.`},{id:`me-le-infinitif`,fr:`Le contrat ? Tu peux ____ transférer par mail ?`,cue:`(le contrat, à moi)`,answer:`me le`,wrong:[`le me`,`me lui`,`le moi`,`moi le`],en:`The contract? Can you forward it to me by email?`,why:`Before the infinitive: me, then le.`},{id:`me-les-negation`,fr:`Paul a toujours mes clés : il ne ____ pas encore rendues.`,cue:`(mes clés, à moi)`,answer:`me les a`,wrong:[`les m'a`,`m'en a`,`me leur a`,`me les ont`],en:`Paul still has my keys: he hasn't given them back to me yet.`,why:`Ne + me + les + auxiliary + pas: the pronouns stay together.`},{id:`la-lui-accord`,fr:`Cette lettre de recommandation ? Je ____ remise en main propre.`,cue:`(la lettre, au directeur)`,answer:`la lui ai`,wrong:[`lui l'ai`,`la leur ai`,`le lui ai`,`lui ai`],en:`That reference letter? I handed it to him in person.`,why:`La before lui; la placed before the auxiliary makes remise agree.`},{id:`les-leur`,fr:`Les nouvelles consignes, tu ____ as expliquées ?`,cue:`(les consignes, aux stagiaires)`,answer:`les leur`,wrong:[`leur les`,`les lui`,`leurs les`,`les y`],en:`The new instructions: have you explained them to the interns?`,why:`Les before leur; leur as a pronoun never takes an s.`},{id:`lui-en`,fr:`Mon frère cherchait des conseils, alors ma sœur ____ a donné quelques-uns.`,cue:`(à mon frère, des conseils)`,answer:`lui en`,wrong:[`en lui`,`lui les`,`leur en`,`y en`],en:`My brother was looking for advice, so my sister gave him a few tips.`,why:`Lui comes before en; quelques-uns stays after the verb.`},{id:`leur-en`,fr:`Les voisins adorent mes confitures, alors ____ apporte un pot chaque automne.`,cue:`(aux voisins, de mes confitures)`,answer:`je leur en`,wrong:[`j'en leur`,`je les en`,`je leur y`,`je leurs en`],en:`The neighbours love my jams, so I take them a jar every autumn.`,why:`Leur before en; en stands for the jam, the quantity (un pot) stays.`},{id:`nous-en`,fr:`Des solutions, le consultant ____ a proposé plusieurs.`,cue:`(à nous, des solutions)`,answer:`nous en`,wrong:[`en nous`,`nous les`,`nous y`,`leur en`],en:`As for solutions, the consultant suggested several to us.`,why:`Nous before en; the participle never agrees with en.`},{id:`vous-en`,fr:`Des échantillons ? Notre service client ____ enverra dès réception de votre commande.`,cue:`(à vous, des échantillons)`,answer:`vous en`,wrong:[`en vous`,`vous les`,`vous y`,`leur en`],en:`Samples? Our customer service will send you some as soon as your order comes in.`,why:`Vous before en; en replaces des + noun.`},{id:`y-en`,fr:`Des places pour le concert ? Oui, ____ encore quelques-unes.`,cue:`(des places)`,answer:`il y en a`,wrong:[`il en y a`,`il y a`,`il les y a`],en:`Concert tickets? Yes, there are still a few left.`,why:`Y comes before en: il y en a.`},{id:`les-y`,fr:`Mes parents devaient être à la gare à 8 h, alors ____ ai conduits en voiture.`,cue:`(mes parents, à la gare)`,answer:`je les y`,wrong:[`j'y les`,`je leur y`,`je les en`],en:`My parents had to be at the station at 8, so I drove them there.`,why:`Les before y: je les y ai conduits.`},{id:`se-les-accord`,fr:`Ces boucles d'oreilles ? Elle ____ est offertes pour ses quarante ans.`,cue:`(les boucles d'oreilles, à elle-même)`,answer:`se les`,wrong:[`s'en`,`les lui`,`se leur`,`lui les`],en:`Those earrings? She treated herself to them for her fortieth birthday.`,why:`Se before les; offertes agrees with les, placed before the auxiliary.`},{id:`negation-pc`,fr:`Je ne ____ pas encore annoncée : j'attends le bon moment.`,cue:`(la nouvelle, à mes parents)`,answer:`la leur ai`,wrong:[`leur l'ai`,`la lui ai`,`leur ai`,`les leur ai`],en:`I haven't told them yet: I'm waiting for the right moment.`,why:`Ne + la + leur + ai + pas; annoncée agrees with la.`},{id:`infinitif-la-leur`,fr:`Ce n'est pas encore officiel, mais je vais ____ présenter lundi.`,cue:`(la décision, aux actionnaires)`,answer:`la leur`,wrong:[`leur la`,`la lui`,`lui la`,`les leur`],en:`It's not official yet, but I'm going to present it to them on Monday.`,why:`With aller + infinitive, both pronouns go before the infinitive: la, then leur.`},{id:`imperatif-le-moi`,fr:`Tu as fini ce roman ? Alors ____ quand tu peux.`,cue:`(prêter : le roman, à moi)`,answer:`prête-le-moi`,wrong:[`prête-moi-le`,`prête-le-me`,`me le prête`,`prêtes-le-moi`],en:`Have you finished that novel? Then lend it to me when you can.`,why:`Affirmative imperative: verb-le-moi, direct object first.`},{id:`imperatif-m-en`,fr:`Ce gâteau est délicieux, ____ encore un petit morceau !`,cue:`(donner : du gâteau, à moi)`,answer:`donne-m'en`,wrong:[`donne-moi-en`,`donne-en-moi`,`m'en donne`,`donne-le-moi`],en:`This cake is delicious, give me another little piece!`,why:`Moi becomes m' before en: donne-m'en.`},{id:`imperatif-lui-en`,fr:`Si tu as des doutes sur ce projet, ____ avant la réunion.`,cue:`(parler : à ta cheffe, de tes doutes)`,answer:`parle-lui-en`,wrong:[`parle-en-lui`,`lui en parle`,`parles-lui-en`,`parle-leur-en`],en:`If you have doubts about this project, talk to your boss about them before the meeting.`,why:`Imperative: verb-lui-en; no s on parle, since lui comes between.`},{id:`imperatif-la-leur`,fr:`La convocation est prête : ____ dès ce soir.`,cue:`(envoyer : la convocation, aux candidats)`,answer:`envoie-la-leur`,wrong:[`envoie-leur-la`,`la leur envoie`,`envoie-la-lui`,`envoies-la-leur`],en:`The notice is ready: send it to them this evening.`,why:`Affirmative imperative: le / la / les before lui / leur.`},{id:`imperatif-negatif`,fr:`C'est une surprise pour Léa : surtout, ne ____ pas !`,cue:`(ça, à Léa)`,answer:`le lui dis`,wrong:[`lui le dis`,`dis-le-lui`,`le-lui dis`,`le leur dis`],en:`It's a surprise for Léa: whatever you do, don't tell her!`,why:`Negative imperative: the normal order before the verb, no hyphens.`}]},{id:`pronoms-y-en`,title:`Complète avec y, en ou le bon pronom`,en:`Fill in y, en or the right pronoun`,level:4,items:[{id:`en-quantite`,fr:`Des candidatures, on ____ a reçu plus de deux cents cette année.`,answer:`en`,wrong:[`les`,`y`,`leur`],en:`As for applications, we received more than two hundred this year.`,why:`En replaces the noun after a quantity; the number stays after the verb.`},{id:`en-il-reste`,fr:`Des exemplaires ? Il ____ reste plus que trois.`,answer:`n'en`,wrong:[`ne les`,`n'y`,`ne le`],en:`Copies? There are only three left.`,why:`Il reste + a quantity: en replaces the noun, the number stays.`},{id:`en-participe`,fr:`Des erreurs, nous ____ avons tous commis.`,answer:`en`,wrong:[`les`,`y`,`leur`],en:`Mistakes? We've all made some.`,why:`En replaces des + noun; the participle never agrees with en.`},{id:`en-se-souvenir`,fr:`Ce voyage en Islande ? Je ____ souviens comme si c'était hier.`,answer:`m'en`,wrong:[`m'y`,`me le`,`me la`],en:`That trip to Iceland? I remember it as if it were yesterday.`,why:`Se souvenir de quelque chose: en.`},{id:`en-etre-capable`,fr:`Il a promis de finir avant lundi, mais je doute qu'il ____ soit capable.`,answer:`en`,wrong:[`y`,`le`,`lui`],en:`He promised to finish before Monday, but I doubt he's up to it.`,why:`Être capable de (faire) quelque chose: en.`},{id:`en-parler`,fr:`Ce projet est confidentiel : ____ parle à personne.`,answer:`n'en`,wrong:[`n'y`,`ne le`,`ne lui`],en:`This project is confidential: don't mention it to anyone.`,why:`Parler de quelque chose: en.`},{id:`y-penser-chose`,fr:`Cet entretien la stresse : elle ____ pense sans arrêt.`,answer:`y`,wrong:[`en`,`lui`,`la`],en:`This interview is stressing her out: she thinks about it constantly.`,why:`Penser à quelque chose: y.`},{id:`y-reflechir`,fr:`Votre proposition ? Nous ____ réfléchissons encore.`,answer:`y`,wrong:[`en`,`la`,`lui`],en:`Your proposal? We're still thinking it over.`,why:`Réfléchir à quelque chose: y.`},{id:`y-renoncer`,fr:`Partir vivre à l'étranger ? Elle ____ a jamais renoncé.`,answer:`n'y`,wrong:[`n'en`,`ne lui`,`ne leur`],en:`Moving abroad? She's never given up on it.`,why:`Renoncer à quelque chose: y.`},{id:`y-lieu`,fr:`Tu connais Lisbonne ? — Oui, nous ____ avons passé une semaine l'an dernier.`,answer:`y`,wrong:[`en`,`lui`,`y en`],en:`Do you know Lisbon? — Yes, we spent a week there last year.`,why:`Y replaces a place (à, en, dans + place).`},{id:`y-tenir`,fr:`Ce n'est pas obligatoire, mais si vous ____ tenez, on peut organiser une visite.`,answer:`y`,wrong:[`en`,`le`,`lui`],en:`It's not compulsory, but if you really want to, we can arrange a visit.`,why:`Y tenir (tenir à quelque chose): to be keen on it.`},{id:`personne-penser-a`,fr:`Ta grand-mère ? Tu sais, ces temps-ci, ____ tous les jours.`,answer:`je pense à elle`,wrong:[`j'y pense`,`je lui pense`,`je la pense`,`j'en pense`],en:`Your grandmother? You know, these days I think about her every day.`,why:`Penser à + a person: à lui / à elle, not y or lui.`},{id:`personne-s-interesser`,fr:`Ce jeune chercheur est brillant ; le directeur du labo ____ depuis son arrivée.`,answer:`s'intéresse à lui`,wrong:[`s'y intéresse`,`s'intéresse de lui`,`s'en intéresse`,`lui intéresse`],en:`This young researcher is brilliant; the head of the lab has taken an interest in him since he arrived.`,why:`S'intéresser à + a person: à lui; y is for things.`},{id:`personne-parler-de`,fr:`Mes beaux-parents ? On parle souvent ____ à la maison.`,answer:`d'eux`,wrong:[`de leur`,`leur`,`de eux`,`d'elles`],en:`My in-laws? We often talk about them at home.`,why:`Parler de + people: de + a stressed pronoun (d'eux), not leur.`},{id:`s-en-aller`,fr:`Il se fait tard, on ____ va.`,answer:`s'en`,wrong:[`s'y`,`se`,`en se`],en:`It's getting late, we're off.`,why:`S'en aller = to leave: on s'en va.`},{id:`en-vouloir`,fr:`Je sais que j'ai été maladroit ; tu ____ veux encore ?`,answer:`m'en`,wrong:[`m'y`,`en me`,`me le`],en:`I know I was clumsy; are you still angry with me?`,why:`En vouloir à quelqu'un = to hold it against them: tu m'en veux.`},{id:`s-y-faire`,fr:`Le décalage horaire est difficile au début, mais on ____ fait vite.`,answer:`s'y`,wrong:[`s'en`,`y se`,`se`],en:`Jet lag is hard at first, but you soon get used to it.`,why:`S'y faire (se faire à quelque chose) = to get used to it.`},{id:`ne-pas-en-revenir`,fr:`Elle a eu le poste ? Je ____ reviens pas !`,answer:`n'en`,wrong:[`n'y`,`ne le`,`ne m'en`],en:`She got the job? I can't believe it!`,why:`Ne pas en revenir = to be amazed, not to get over it.`},{id:`s-en-sortir`,fr:`Malgré la crise, la petite librairie ____ sort plutôt bien.`,answer:`s'en`,wrong:[`s'y`,`se`,`en se`],en:`Despite the crisis, the little bookshop is doing rather well.`,why:`S'en sortir = to manage, to cope.`},{id:`en-avoir-assez`,fr:`Les réunions de trois heures, ____ vraiment assez.`,answer:`j'en ai`,wrong:[`j'y ai`,`je les ai`,`j'ai`],en:`Three-hour meetings: I've really had enough of them.`,why:`En avoir assez (de quelque chose) = to be fed up with it.`},{id:`y-etre-pour-rien`,fr:`Ne l'accuse pas, il ____ est pour rien.`,answer:`n'y`,wrong:[`n'en`,`ne lui`,`ne s'en`],en:`Don't blame him, it's nothing to do with him.`,why:`N'y être pour rien = to have nothing to do with it.`},{id:`s-en-faire`,fr:`Tu ____ fais pour rien, tout va bien se passer.`,answer:`t'en`,wrong:[`te`,`en te`,`t'y`],en:`You're worrying about nothing, it's all going to be fine.`,why:`S'en faire = to worry: tu t'en fais.`},{id:`s-en-tenir`,fr:`Ne spéculons pas : ____ aux faits.`,cue:`(s'en tenir)`,answer:`tenons-nous-en`,wrong:[`tenons-nous-y`,`tenons-en-nous`,`nous en tenons`,`tenons-en`],en:`Let's not speculate: let's stick to the facts.`,why:`S'en tenir à = to stick to; in the imperative: tenons-nous-en.`}]}],i=[{id:`cause-consequence`,title:`Exprime la cause ou la conséquence`,en:`Express the cause or the consequence`,level:4,items:[{id:`a-cause-de-la-greve`,fr:`Le vol a été annulé ____ la grève des contrôleurs aériens.`,answer:`à cause de`,accept:[`en raison de`,`du fait de`],wrong:[`grâce à`,`parce que`,`faute de`,`puisque`],en:`The flight was cancelled because of the air traffic controllers' strike.`,why:`A noun follows and the outcome is bad: à cause de, or the neutral, formal en raison de.`},{id:`grace-a-son-dossier`,fr:`Elle a obtenu la bourse sans difficulté ____ son excellent dossier.`,answer:`grâce à`,accept:[`en raison de`,`du fait de`],wrong:[`à cause de`,`parce que`,`faute de`,`grâce au`],en:`She got the scholarship easily thanks to her excellent record.`,why:`A noun with a good outcome: grâce à (à cause de is for bad outcomes).`},{id:`faute-de-financement`,fr:`Le projet a été abandonné ____ financement.`,answer:`faute de`,accept:[`par manque de`],wrong:[`à cause de`,`grâce à`,`en raison de`],en:`The project was dropped for lack of funding.`,why:`Faute de + a noun with no article means "for lack of".`},{id:`a-cause-des-embouteillages`,fr:`Nous avons raté le train ____ embouteillages.`,answer:`à cause des`,accept:[`en raison des`],wrong:[`à cause de les`,`grâce aux`,`parce que les`],en:`We missed the train because of the traffic jams.`,why:`À cause de + les contracts to à cause des; grâce à is only for good outcomes.`},{id:`vu-la-situation`,fr:`Il vaut mieux reporter le voyage, ____ la situation.`,answer:`vu`,accept:[`étant donné`,`en raison de`,`compte tenu de`,`à cause de`],wrong:[`vu que`,`parce que`,`grâce à`,`puisque`],en:`Given the situation, it would be better to postpone the trip.`,why:`Vu or étant donné can be followed directly by a noun; vu que and parce que need a clause.`},{id:`etant-donne-que`,fr:`Nous devons commencer dès aujourd'hui, ____ que les délais sont très courts.`,answer:`étant donné`,accept:[`vu`,`du fait`,`attendu`],wrong:[`à cause`,`grâce`,`en raison`,`faute`],en:`We have to start today, given that the deadlines are very tight.`,why:`Étant donné que and vu que introduce a clause; à cause, grâce and en raison need de or à + a noun.`},{id:`comme-en-tete`,fr:`Il était tard et, ____ nous habitions loin, nous avons dormi sur place.`,answer:`comme`,accept:[`puisque`,`vu que`,`étant donné que`,`parce que`],wrong:[`car`,`donc`,`grâce à`,`si bien que`],en:`It was late and, as we lived far away, we stayed the night.`,why:`Comme gives the cause before the main clause; car can only come after it.`},{id:`sous-pretexte-que`,fr:`Il a refusé de m'aider ____ était débordé, ce dont je doute.`,cue:`(supposedly because)`,answer:`sous prétexte qu'il`,wrong:[`parce qu'il`,`à cause qu'il`,`grâce qu'il`,`d'autant plus qu'il`],en:`He refused to help me on the pretext that he was swamped, which I doubt.`,why:`Sous prétexte que gives a reason the speaker does not believe.`},{id:`d-autant-plus-que`,fr:`Cette promotion me fait très plaisir, ____ je ne m'y attendais pas du tout.`,cue:`(all the more so as)`,answer:`d'autant plus que`,accept:[`d'autant que`],wrong:[`sous prétexte que`,`si bien que`,`au point que`],en:`I'm delighted with this promotion, all the more so as I wasn't expecting it at all.`,why:`D'autant plus que adds a reason that strengthens what was just said.`},{id:`si-bien-que-neige`,fr:`Il a beaucoup neigé cette nuit, ____ les écoles sont fermées.`,answer:`si bien que`,accept:[`de sorte que`,`donc`,`par conséquent`,`c'est pourquoi`],wrong:[`parce que`,`puisque`,`bien que`,`car`],en:`It snowed heavily last night, so the schools are closed.`,why:`The second clause is the result: si bien que (or de sorte que, donc, par conséquent…).`},{id:`de-sorte-que-indicatif`,fr:`Le gouvernement a réduit les subventions, de sorte que beaucoup d'associations ____ fermer.`,cue:`(devoir, passé composé)`,answer:`ont dû`,wrong:[`aient dû`,`ont dus`,`doivent`],en:`The government cut subsidies, so many charities had to close.`,why:`De sorte que stating a result takes the indicative (the subjunctive would turn it into a purpose).`},{id:`si-vite-que`,fr:`Elle parle ____ vite que personne ne la comprend.`,answer:`si`,accept:[`tellement`],wrong:[`tant`,`trop`,`très`,`autant`],en:`She speaks so fast that nobody understands her.`,why:`Si or tellement + adjective or adverb + que: an intensity that causes a result.`},{id:`tellement-de-monde`,fr:`Il y avait ____ monde que nous n'avons pas pu entrer.`,answer:`tellement de`,accept:[`tant de`],wrong:[`si`,`tellement`,`trop de`,`beaucoup de`],en:`There were so many people that we couldn't get in.`,why:`Before a noun: tant de or tellement de + noun + que.`},{id:`tellement-travaille`,fr:`Elle a ____ travaillé qu'elle a fini par craquer.`,answer:`tellement`,accept:[`tant`],wrong:[`si`,`tellement de`,`très`,`trop`],en:`She worked so hard that she ended up cracking.`,why:`With a verb, use tant or tellement; si only goes before an adjective or an adverb.`},{id:`tellement-augmente-que`,fr:`Les loyers ont tellement augmenté ____ beaucoup de familles quittent le centre-ville.`,answer:`que`,wrong:[`si bien que`,`donc`,`de sorte que`],en:`Rents have risen so much that many families are leaving the city centre.`,why:`Tellement after a verb is completed by que + the consequence.`},{id:`un-tel-succes`,fr:`Le concert a été un tel succès ____ deuxième date a été ajoutée.`,answer:`qu'une`,wrong:[`si bien qu'une`,`donc une`,`de sorte qu'une`],en:`The concert was such a success that a second date was added.`,why:`Un tel + noun is completed by que + the consequence.`},{id:`au-point-que`,fr:`Le stress est devenu insupportable, ____ a dû se mettre en arrêt maladie.`,cue:`(to the point that)`,answer:`au point qu'elle`,accept:[`à tel point qu'elle`],wrong:[`parce qu'elle`,`bien qu'elle`,`afin qu'elle`,`à moins qu'elle`],en:`The stress became unbearable, to the point that she had to go on sick leave.`,why:`Au point que (+ indicative) introduces an extreme consequence.`},{id:`d-ou-la-greve`,fr:`Les négociations ont échoué, ____ la grève prévue pour lundi.`,answer:`d'où`,wrong:[`donc`,`si bien que`,`c'est pourquoi`,`par conséquent`],en:`Talks broke down, hence the strike planned for Monday.`,why:`D'où is followed by a noun; donc and the others need a full clause.`},{id:`c-est-pourquoi`,fr:`Il ne supporte pas l'avion ; ____ voyage toujours en train.`,answer:`c'est pourquoi il`,accept:[`donc il`,`par conséquent il`,`voilà pourquoi il`,`c'est pour ça qu'il`,`c'est pour cela qu'il`],wrong:[`c'est parce qu'il`,`car il`,`puisqu'il`],en:`He can't stand flying, which is why he always travels by train.`,why:`C'est pourquoi introduces the consequence; car and puisque would introduce a cause.`},{id:`par-consequent`,fr:`Le budget a été réduit de moitié ; ____, plusieurs postes seront supprimés.`,answer:`par conséquent`,accept:[`en conséquence`,`donc`,`de ce fait`],wrong:[`parce que`,`puisque`,`grâce à`,`d'où`],en:`The budget has been halved; consequently, several jobs will be cut.`,why:`Par conséquent links two independent clauses to state a result; d'où would need a noun.`}]},{id:`but`,title:`Exprime le but`,en:`Express purpose`,level:3,items:[{id:`pour-que-lien`,fr:`Je t'envoie le lien ____ tu puisses t'inscrire.`,answer:`pour que`,accept:[`afin que`],wrong:[`pour`,`afin de`,`parce que`,`de peur que`],en:`I'm sending you the link so that you can sign up.`,why:`Different subjects (je / tu): pour que or afin que + subjunctive.`},{id:`pour-s-acheter`,fr:`Elle économise depuis des années ____ s'acheter un appartement.`,answer:`pour`,accept:[`afin de`],wrong:[`pour que`,`afin que`,`de peur de`,`pour de`],en:`She's been saving for years to buy a flat.`,why:`Same subject: pour or afin de + infinitive.`},{id:`afin-de-vous-informer`,fr:`Je vous écris ____ vous informer que votre demande a été acceptée.`,answer:`afin de`,accept:[`pour`],wrong:[`afin que`,`pour que`,`de peur de`],en:`I am writing to inform you that your application has been accepted.`,why:`Same subject: afin de (or pour) + infinitive; afin que would need a new subject and a subjunctive.`},{id:`afin-d-eviter`,fr:`Nous partirons à l'aube ____ la chaleur.`,answer:`afin d'éviter`,accept:[`pour éviter`,`de manière à éviter`,`de façon à éviter`],wrong:[`afin que nous évitions`,`pour que nous évitions`,`de peur d'éviter`],en:`We'll set off at dawn to avoid the heat.`,why:`Same subject (nous): afin de + infinitive, never afin que nous…`},{id:`pour-que-comprenne`,fr:`Je vais répéter la consigne pour que tout le monde la ____.`,cue:`(comprendre)`,answer:`comprenne`,wrong:[`comprend`,`comprendra`,`comprendre`,`comprennent`],en:`I'll repeat the instructions so that everyone understands them.`,why:`Pour que always takes the subjunctive; tout le monde is singular.`},{id:`afin-que-puissent`,fr:`Le rapport a été traduit en anglais afin que les investisseurs étrangers ____ le lire.`,cue:`(pouvoir)`,answer:`puissent`,wrong:[`peuvent`,`pourront`,`puisse`,`pouvoir`],en:`The report was translated into English so that foreign investors could read it.`,why:`Afin que always takes the subjunctive: puissent, plural like les investisseurs.`},{id:`de-facon-que-puisse`,fr:`Placez les chaises de façon que tout le monde ____ voir l'écran.`,cue:`(pouvoir)`,answer:`puisse`,wrong:[`peut`,`pourra`,`puissent`,`pouvoir`],en:`Arrange the chairs so that everyone can see the screen.`,why:`De façon que expressing a purpose takes the subjunctive.`},{id:`afin-que-les`,fr:`On a installé des rampes ____ personnes à mobilité réduite puissent accéder au bâtiment.`,answer:`afin que les`,accept:[`pour que les`],wrong:[`afin de les`,`pour les`,`de façon à les`],en:`Ramps have been installed so that people with reduced mobility can get into the building.`,why:`A new subject (les personnes) needs afin que or pour que + subjunctive.`},{id:`pour-que-la-piece`,fr:`Laisse la fenêtre entrouverte ____ la pièce s'aère.`,answer:`pour que`,accept:[`afin que`,`de façon que`,`de manière que`,`de sorte que`],wrong:[`pour`,`afin de`,`de manière à`],en:`Leave the window ajar so that the room airs out.`,why:`La pièce is a new subject: pour que + subjunctive (s'aère).`},{id:`de-peur-d-etre`,fr:`Il a pris un parapluie ____ trempé.`,answer:`de peur d'être`,accept:[`pour ne pas être`,`de crainte d'être`],wrong:[`de peur qu'il soit`,`afin d'être`,`pour être`],en:`He took an umbrella so as not to get soaked.`,why:`Same subject: de peur de + infinitive (de peur que is for a different subject).`},{id:`pour-ne-pas-rater`,fr:`Il est parti tôt ____ son train.`,answer:`pour ne pas rater`,accept:[`de peur de rater`,`de crainte de rater`,`afin de ne pas rater`],wrong:[`pour ne rater pas`,`pour rater`,`pour non rater`],en:`He left early so as not to miss his train.`,why:`With an infinitive, ne pas goes together before the verb: pour ne pas rater.`},{id:`de-peur-qu-elle-ne`,fr:`Je ne lui ai rien dit ____ s'inquiète.`,answer:`de peur qu'elle ne`,accept:[`de peur qu'elle`,`de crainte qu'elle ne`,`de crainte qu'elle`],wrong:[`de peur de`,`pour qu'elle`,`afin qu'elle`],en:`I didn't tell her anything for fear she'd worry.`,why:`Different subjects: de peur que + subjunctive, with an optional expletive ne.`},{id:`de-peur-que-plaignent`,fr:`Parle moins fort, de peur que les voisins ne ____.`,cue:`(se plaindre)`,answer:`se plaignent`,wrong:[`se plaindront`,`se plaindre`,`se plaignant`,`se plaigne`],en:`Keep your voice down, in case the neighbours complain.`,why:`De peur que takes the subjunctive, often with an expletive ne that is not negative.`},{id:`de-crainte-que-propage`,fr:`Les pompiers ont évacué le quartier de crainte que l'incendie ne ____.`,cue:`(se propager)`,answer:`se propage`,wrong:[`se propageait`,`se propagera`,`se propager`,`propage`],en:`Firefighters evacuated the neighbourhood for fear the fire would spread.`,why:`De crainte que, like de peur que, takes the subjunctive, often with an expletive ne.`},{id:`de-maniere-a`,fr:`Nous avons classé les dossiers par date ____ les retrouver facilement.`,answer:`de manière à`,accept:[`de façon à`,`pour`,`afin de`],wrong:[`de manière que`,`de façon que`,`pour que`],en:`We filed the documents by date so as to find them easily.`,why:`Same subject: de manière à or de façon à + infinitive.`},{id:`de-maniere-que`,fr:`Elle articule chaque mot ____ que tout le monde la comprenne.`,answer:`de manière`,accept:[`de façon`,`de sorte`,`pour`,`afin`],wrong:[`de manière à`,`de peur`,`en vue`],en:`She articulates every word so that everyone understands her.`,why:`Before a clause with its own subject: de manière que + subjunctive; de manière à needs an infinitive.`},{id:`en-vue-du-marathon`,fr:`Elle s'entraîne tous les jours ____ marathon de Paris.`,answer:`en vue du`,accept:[`pour le`],wrong:[`en vue de`,`afin du`,`pour du`],en:`She trains every day for the Paris marathon.`,why:`En vue de + noun expresses an aim; de + le contracts to du.`},{id:`en-vue-d-obtenir`,fr:`Il suit des cours du soir ____ une promotion.`,answer:`en vue d'obtenir`,accept:[`afin d'obtenir`,`pour obtenir`,`de manière à obtenir`],wrong:[`en vue qu'il obtienne`,`afin qu'il obtienne`,`pour qu'il obtient`],en:`He's taking evening classes with a view to getting a promotion.`,why:`Same subject, so an infinitive: en vue de + infinitive expresses a longer-term aim.`},{id:`en-vue-de-la-reforme`,fr:`Le gouvernement a lancé une consultation ____ la réforme des retraites.`,answer:`en vue de`,accept:[`pour`],wrong:[`afin de`,`pour que`,`de manière à`],en:`The government has launched a consultation ahead of the pension reform.`,why:`En vue de can be followed by a noun; afin de and de manière à only take an infinitive.`}]},{id:`concession-opposition`,title:`Exprime la concession ou l'opposition`,en:`Express concession or contrast`,level:4,items:[{id:`bien-qu-il-soit-tard`,fr:`Bien qu'il ____ très tard, elle a continué à travailler.`,cue:`(être)`,answer:`soit`,accept:[`fût`],wrong:[`était`,`est`,`sera`],en:`Although it was very late, she kept on working.`,why:`Bien que always takes the subjunctive.`},{id:`bien-qu-elle-ait-travaille`,fr:`Bien qu'elle ____ toute la nuit, elle n'a pas terminé sa thèse.`,cue:`(travailler)`,answer:`ait travaillé`,wrong:[`a travaillé`,`avait travaillé`,`travaille`,`aie travaillé`],en:`Although she worked all night, she didn't finish her thesis.`,why:`Bien que + subjunctive; the work is over, so the past subjunctive: ait travaillé.`},{id:`bien-que-salaire`,fr:`Il a accepté le poste, ____ le salaire soit modeste.`,answer:`bien que`,accept:[`quoique`,`encore que`],wrong:[`même si`,`malgré`,`alors que`,`pourtant`],en:`He took the job, although the salary is modest.`,why:`Soit is subjunctive, so only bien que or quoique fit; même si and alors que take the indicative.`},{id:`quoiqu-il-soit`,fr:`Il manque d'expérience, ____ soit très compétent.`,answer:`quoiqu'il`,accept:[`bien qu'il`,`encore qu'il`],wrong:[`quoi qu'il`,`même s'il`,`alors qu'il`],en:`He lacks experience, although he's very competent.`,why:`Quoique in one word means "although" (= bien que) and takes the subjunctive.`},{id:`meme-s-il-pleut`,fr:`Même s'il ____ demain, le match aura lieu.`,cue:`(pleuvoir)`,answer:`pleut`,wrong:[`pleuve`,`pleuvra`,`pleuvait`],en:`Even if it rains tomorrow, the match will go ahead.`,why:`Même si works like si: present indicative, never the subjunctive or the future.`},{id:`meme-si-tu-as-raison`,fr:`Même si tu ____ raison, ce n'est pas une raison pour crier.`,cue:`(avoir)`,answer:`as`,wrong:[`aies`,`auras`,`ayes`],en:`Even if you're right, that's no reason to shout.`,why:`Même si is followed by the indicative, never the subjunctive.`},{id:`alors-que-le-train`,fr:`Il a pris l'avion, alors que le train ____ plus écologique.`,cue:`(être, imparfait)`,answer:`était`,wrong:[`soit`,`ait été`,`étant`],en:`He flew, even though the train was the greener option.`,why:`Alors que (contrast) takes the indicative, unlike bien que.`},{id:`malgre-la-pluie`,fr:`Des milliers de personnes ont défilé dans les rues ____ la pluie.`,answer:`malgré`,accept:[`en dépit de`],wrong:[`bien que`,`même si`,`malgré que`,`quoique`],en:`Thousands of people marched in the streets despite the rain.`,why:`Before a noun: malgré or en dépit de; bien que and même si need a clause.`},{id:`en-depit-des`,fr:`L'usine a été fermée ____ protestations des salariés.`,answer:`en dépit des`,accept:[`malgré les`],wrong:[`en dépit de les`,`bien que les`,`même si les`],en:`The factory was closed despite the workers' protests.`,why:`En dépit de + les contracts to en dépit des (or use malgré les).`},{id:`avoir-beau-faire`,fr:`Il a beau ____ des efforts, il n'arrive pas à rattraper son retard.`,cue:`(faire)`,answer:`faire`,wrong:[`fait`,`faisant`,`fasse`],en:`However hard he tries, he can't catch up.`,why:`Avoir beau is followed by an infinitive: "however much…".`},{id:`elles-ont-beau`,fr:`Elles ____ beau insister, le directeur ne cédera pas.`,cue:`(avoir)`,answer:`ont`,accept:[`auront`],wrong:[`sont`,`a`,`avaient`],en:`However much they insist, the director won't give in.`,why:`In avoir beau, avoir is conjugated to agree with the subject.`},{id:`quoi-qu-ils-proposent`,fr:`Ne signe rien, ____ te proposent.`,answer:`quoi qu'ils`,wrong:[`quoiqu'ils`,`ce qu'ils`,`bien qu'ils`],en:`Do not sign anything, whatever they offer you.`,why:`Quoi que in two words means "whatever" and takes the subjunctive; quoiqu'ils would mean "although they".`},{id:`ou-que-vous-alliez`,fr:`Où que vous ____ en France, vous trouverez une boulangerie.`,cue:`(aller)`,answer:`alliez`,wrong:[`allez`,`irez`,`aillez`],en:`Wherever you go in France, you'll find a bakery.`,why:`Où que (wherever) is followed by the subjunctive: que vous alliez.`},{id:`qui-que-vous-soyez`,fr:`Qui que vous ____, vous devez présenter une pièce d'identité.`,cue:`(être)`,answer:`soyez`,wrong:[`êtes`,`serez`,`soyiez`],en:`Whoever you are, you must show ID.`,why:`Qui que (whoever) takes the subjunctive: soyez, with no i.`},{id:`pourtant-film`,fr:`Le film a reçu de mauvaises critiques ; il a ____ attiré plus d'un million de spectateurs.`,answer:`pourtant`,accept:[`cependant`,`néanmoins`,`toutefois`,`quand même`,`tout de même`],wrong:[`malgré`,`bien que`,`même si`,`au lieu de`],en:`The film got bad reviews; yet it drew more than a million viewers.`,why:`An adverb fits between two clauses: pourtant, cependant, néanmoins, toutefois.`},{id:`quand-meme`,fr:`C'était cher, mais on l'a acheté ____.`,answer:`quand même`,accept:[`tout de même`,`malgré tout`],wrong:[`malgré`,`bien que`,`même si`],en:`It was expensive, but we bought it anyway.`,why:`Quand même (or tout de même) at the end means "anyway, all the same".`},{id:`tandis-que`,fr:`Mon frère est très sociable, ____ ma sœur est plutôt réservée.`,answer:`tandis que`,accept:[`alors que`,`mais`],wrong:[`bien que`,`quoique`,`malgré`],en:`My brother is very outgoing, whereas my sister is rather reserved.`,why:`Tandis que and alors que contrast two facts and take the indicative (est).`},{id:`en-revanche`,fr:`Les ventes ont chuté en Europe ; ____, elles ont doublé en Asie.`,answer:`en revanche`,accept:[`par contre`,`à l'inverse`,`inversement`],wrong:[`au lieu de`,`malgré`,`bien que`,`alors que`],en:`Sales fell in Europe; in Asia, on the other hand, they doubled.`,why:`En revanche (or par contre) introduces a contrasting fact, as an adverb between two clauses.`},{id:`au-contraire`,fr:`Ce n'est pas une mauvaise nouvelle, ____ : c'est la meilleure de l'année !`,answer:`au contraire`,accept:[`bien au contraire`],wrong:[`en revanche`,`par contre`,`pourtant`],en:`It's not bad news, quite the opposite: it's the best news of the year!`,why:`Au contraire contradicts a negative statement and asserts the opposite.`},{id:`au-lieu-de`,fr:`Elle a proposé des solutions ____ se plaindre.`,answer:`au lieu de`,accept:[`plutôt que de`,`plutôt que`],wrong:[`au lieu`,`malgré`,`en revanche`],en:`Instead of complaining, she came up with solutions.`,why:`Au lieu de + infinitive: instead of doing.`}]}],a=[{id:`mise-en-relief`,title:`Complète la phrase mise en relief`,en:`Complete the cleft sentence`,level:4,items:[{id:`moi-qui-ai`,fr:`C'est moi qui ____ raison, pas toi.`,cue:`(avoir)`,answer:`ai`,wrong:[`a`,`as`,`avons`],en:`I'm the one who's right, not you.`,why:`After c'est moi qui, the verb agrees with moi: j'ai → c'est moi qui ai.`},{id:`nous-qui-avons`,fr:`C'est nous qui ____ organisé la soirée.`,cue:`(avoir)`,answer:`avons`,wrong:[`ont`,`a`,`avez`],en:`We were the ones who organised the party.`,why:`The verb after qui agrees with the stressed pronoun nous.`},{id:`vous-qui-etes`,fr:`C'est vous qui ____ en retard, pas nous.`,cue:`(être)`,answer:`êtes`,wrong:[`est`,`sont`,`soyez`],en:`You're the ones who are late, not us.`,why:`The verb after qui agrees with vous, not with c'est.`},{id:`toi-qui-as`,fr:`C'est toi qui ____ les clés de la salle ?`,cue:`(avoir)`,answer:`as`,wrong:[`a`,`ai`,`avez`],en:`Are you the one who has the keys to the room?`,why:`The verb agrees with toi: c'est toi qui as.`},{id:`toi-et-moi-allons`,fr:`C'est toi et moi qui ____ décider.`,cue:`(aller)`,answer:`allons`,wrong:[`vont`,`va`,`allez`],en:`It's you and me who are going to decide.`,why:`Toi et moi = nous, so the verb after qui takes the nous form.`},{id:`collegues-qui-ont`,fr:`Ce sont mes collègues qui ____ choisi la date.`,cue:`(avoir)`,answer:`ont`,wrong:[`a`,`avons`,`sont`],en:`My colleagues were the ones who chose the date.`,why:`The verb after qui agrees with the stressed noun: mes collègues ont.`},{id:`argent-qui`,fr:`Ce n'est pas l'argent ____ le motive, c'est la reconnaissance.`,answer:`qui`,wrong:[`que`,`dont`,`lequel`,`ce qui`],en:`It's not money that motivates him, it's recognition.`,why:`L'argent is the subject of motive, so c'est… qui.`},{id:`lui-qui`,fr:`C'est lui ____ m'a recommandée pour ce poste.`,answer:`qui`,wrong:[`que`,`qu'il`,`dont`],en:`He was the one who recommended me for this job.`,why:`Lui is the subject of a recommandé, so c'est lui qui.`},{id:`decision-que`,fr:`C'est cette décision ____ je regrette le plus.`,answer:`que`,wrong:[`qui`,`dont`,`laquelle`,`ce que`],en:`It's that decision I regret most.`,why:`Cette décision is the object of regretter, so c'est… que.`},{id:`a-toi-que`,fr:`C'est à toi ____ je pensais en écrivant cette chanson.`,answer:`que`,wrong:[`à qui`,`qui`,`dont`,`auquel`],en:`It was you I was thinking of when I wrote this song.`,why:`The preposition is already in front (c'est à toi), so the link word is simply que.`},{id:`de-ce-projet-que`,fr:`C'est de ce projet ____ je voulais vous parler.`,answer:`que`,wrong:[`dont`,`duquel`,`qui`,`de quoi`],en:`It's this project that I wanted to talk to you about.`,why:`De is already there (c'est de ce projet), so use que; dont would say de twice.`},{id:`pour-cette-raison-que`,fr:`C'est pour cette raison ____ j'ai démissionné.`,answer:`que`,wrong:[`pour laquelle`,`qui`,`dont`,`pourquoi`],en:`That's the reason I resigned.`,why:`The preposition is already in front (pour cette raison), so que is enough.`},{id:`a-lisbonne-que`,fr:`C'est à Lisbonne ____ nous nous sommes rencontrés.`,answer:`que`,wrong:[`où`,`qui`,`dont`],en:`It was in Lisbon that we met.`,why:`After c'est + a place phrase, the link word is que, not où.`},{id:`en-2008-qu-elle`,fr:`C'est en 2008 ____ a fondé son entreprise.`,answer:`qu'elle`,wrong:[`où elle`,`quand elle`,`qui`,`lorsqu'elle`],en:`It was in 2008 that she founded her company.`,why:`After c'est + a time phrase, use que, not où or quand.`},{id:`ce-qui-derange`,fr:`Dans cette affaire, ____ me dérange, c'est le manque de transparence.`,answer:`ce qui`,wrong:[`ce que`,`ce dont`,`qu'est-ce qui`,`qui`],en:`In this business, what bothers me is the lack of transparency.`,why:`Ce qui is the subject of dérange.`},{id:`ce-que-admire`,fr:`Au fond, ____ j'admire le plus chez elle, c'est son courage.`,answer:`ce que`,wrong:[`ce qui`,`ce dont`,`que`,`quoi`],en:`Deep down, what I admire most about her is her courage.`,why:`Ce que is the direct object of admirer (j'admire quelque chose).`},{id:`ce-dont-besoin`,fr:`Honnêtement, ____ j'ai besoin, c'est de vacances.`,answer:`ce dont`,wrong:[`ce que`,`ce qui`,`de quoi`,`dont`],en:`Honestly, what I need is a holiday.`,why:`Avoir besoin de → ce dont; the de comes back after c'est.`},{id:`ce-dont-fiere`,fr:`Ce ____ je suis le plus fière, c'est d'avoir terminé ce marathon.`,answer:`dont`,wrong:[`que`,`qui`,`de quoi`],en:`What I'm proudest of is having finished this marathon.`,why:`Être fier de → ce dont.`},{id:`ce-a-quoi`,fr:`En ce moment, ____ je m'intéresse surtout, c'est à l'histoire de l'art.`,answer:`ce à quoi`,wrong:[`ce que`,`ce dont`,`ce qui`,`à quoi`],en:`At the moment, what I'm mostly interested in is art history.`,why:`S'intéresser à → ce à quoi, and the à comes back after c'est.`}]},{id:`place-adjectifs`,title:`Place et accorde l'adjectif`,en:`Put the adjective in the right place, with the right agreement`,level:4,items:[{id:`ancien-patron`,fr:`J'ai croisé mon ____ dans le métro : il est à la retraite maintenant.`,cue:`(ancien, patron: former boss)`,answer:`ancien patron`,wrong:[`patron ancien`,`ancienne patron`,`anciens patron`],en:`I ran into my former boss on the metro: he has retired now.`,why:`Before the noun, ancien means "former"; after it, "old, historic".`},{id:`maison-ancienne`,fr:`Ils habitent une ____ au cœur du Marais.`,cue:`(ancien, maison: old house)`,answer:`maison ancienne`,wrong:[`ancienne maison`,`maison ancien`,`maison anciennes`],en:`They live in an old house in the heart of the Marais.`,why:`After the noun, ancien means "old, historic"; before it, "former".`},{id:`grand-homme`,fr:`Pour beaucoup de Français, de Gaulle reste un ____.`,cue:`(grand, homme: great man)`,answer:`grand homme`,wrong:[`homme grand`,`grande homme`,`grands hommes`],en:`For many French people, de Gaulle remains a great man.`,why:`Before homme, grand means "great"; un homme grand is simply a tall man.`},{id:`voiture-chere`,fr:`Je n'ai pas les moyens de m'offrir une ____.`,cue:`(cher, voiture: expensive car)`,answer:`voiture chère`,wrong:[`chère voiture`,`voiture cher`,`chères voiture`],en:`I can't afford an expensive car.`,why:`After the noun, cher means "expensive"; before it, "dear".`},{id:`pauvre-femme`,fr:`Elle a perdu son emploi et son appartement la même semaine, la ____ !`,cue:`(pauvre, femme: poor thing)`,answer:`pauvre femme`,wrong:[`femme pauvre`,`pauvres femme`,`pauvre femmes`],en:`She lost her job and her flat in the same week, the poor woman!`,why:`Before the noun, pauvre expresses pity; after it, it means "without money".`},{id:`propres-yeux`,fr:`Je l'ai vu de mes ____, je t'assure.`,cue:`(propre, yeux: own eyes)`,answer:`propres yeux`,wrong:[`yeux propres`,`propre yeux`,`propres œils`],en:`I saw it with my own eyes, I promise you.`,why:`Before the noun, propre means "own"; after it, "clean".`},{id:`chemise-propre`,fr:`Mets une ____, on a des invités ce soir.`,cue:`(propre, chemise: clean shirt)`,answer:`chemise propre`,wrong:[`propre chemise`,`chemise propres`,`propres chemise`],en:`Put on a clean shirt, we've got guests tonight.`,why:`After the noun, propre means "clean".`},{id:`seule-personne`,fr:`Elle est la ____ à avoir voté contre.`,cue:`(seul, personne: only person)`,answer:`seule personne`,wrong:[`personne seule`,`seul personne`,`seules personnes`],en:`She is the only person who voted against.`,why:`Before the noun, seul means "only"; after it, "alone, lonely".`},{id:`femme-seule`,fr:`Depuis la mort de son mari, c'est une ____.`,cue:`(seul, femme: lonely woman)`,answer:`femme seule`,wrong:[`seule femme`,`femme seul`,`femmes seules`],en:`Since her husband died, she has been a lonely woman.`,why:`After the noun, seul means "alone, lonely".`},{id:`jour-meme`,fr:`Elle a démissionné le ____ de son embauche.`,cue:`(même, jour: the very day)`,answer:`jour même`,wrong:[`même jour`,`jour mêmes`,`mêmes jour`],en:`She resigned on the very day she was hired.`,why:`After the noun, même means "very, itself"; before it, "same".`},{id:`meme-jour`,fr:`Nous sommes nés le ____, à deux ans d'écart.`,cue:`(même, jour: same day)`,answer:`même jour`,wrong:[`jour même`,`mêmes jour`,`même jours`],en:`We were born on the same day, two years apart.`,why:`Before the noun, même means "same".`},{id:`certaine-experience`,fr:`J'ai une ____ de la gestion de projet, mais je ne suis pas experte.`,cue:`(certain, expérience: some experience)`,answer:`certaine expérience`,wrong:[`expérience certaine`,`certain expérience`,`certaines expérience`],en:`I have some experience of project management, but I'm not an expert.`,why:`Before the noun, certain means "some, a degree of"; after it, "definite, undeniable".`},{id:`semaine-derniere`,fr:`On s'est vus la ____, au mariage de Paul.`,cue:`(dernier, semaine: last week)`,answer:`semaine dernière`,wrong:[`dernière semaine`,`semaine dernier`,`dernier semaine`],en:`We saw each other last week, at Paul's wedding.`,why:`After a time word, dernier means "the one just gone"; before it, "the final one".`},{id:`derniere-semaine`,fr:`C'est la ____ avant les vacances, tout le monde est épuisé.`,cue:`(dernier, semaine: final week)`,answer:`dernière semaine`,wrong:[`semaine dernière`,`dernier semaine`,`dernières semaine`],en:`It's the final week before the holidays, everyone is exhausted.`,why:`Before the noun, dernier means "last in a series, final".`},{id:`prochain-train`,fr:`Le ____ part dans dix minutes.`,cue:`(prochain, train: next train)`,answer:`prochain train`,wrong:[`train prochain`,`prochaine train`,`prochains train`],en:`The next train leaves in ten minutes.`,why:`For the next one in a series, prochain goes before the noun; after it only with time words (la semaine prochaine).`},{id:`enfant-curieuse`,fr:`Ma fille est une ____ : elle veut tout comprendre.`,cue:`(curieux, enfant: inquisitive child)`,answer:`enfant curieuse`,wrong:[`curieuse enfant`,`enfant curieux`,`curieux enfant`],en:`My daughter is an inquisitive child: she wants to understand everything.`,why:`After the noun, curieux means "inquisitive"; before it, "strange, odd".`},{id:`brave-homme`,fr:`Mon voisin est un ____ : il m'aide toujours à porter mes courses.`,cue:`(brave, homme: decent man)`,answer:`brave homme`,wrong:[`homme brave`,`braves homme`,`brave hommes`],en:`My neighbour is a decent sort: he always helps me carry my shopping.`,why:`Before the noun, brave means "decent, kind"; after it, "brave, courageous".`},{id:`simple-formalite`,fr:`Ne t'inquiète pas, ce n'est qu'une ____.`,cue:`(simple, formalité: mere formality)`,answer:`simple formalité`,wrong:[`formalité simple`,`simples formalité`,`simple formalités`],en:`Don't worry, it's a mere formality.`,why:`Before the noun, simple means "mere, just"; after it, "simple, easy".`},{id:`sale-temps`,fr:`Quel ____ ! Il pleut depuis trois jours.`,cue:`(sale, temps: lousy weather)`,answer:`sale temps`,wrong:[`temps sale`,`sales temps`,`sale temp`],en:`What lousy weather! It's been raining for three days.`,why:`Before the noun, sale means "nasty, lousy"; after it, "dirty".`},{id:`vaisselle-sale`,fr:`Il reste une pile de ____ dans l'évier.`,cue:`(sale, vaisselle: dirty dishes)`,answer:`vaisselle sale`,wrong:[`sale vaisselle`,`vaisselle sales`,`sales vaisselle`],en:`There's still a pile of dirty dishes in the sink.`,why:`After the noun, sale means "dirty".`},{id:`histoire-vraie`,fr:`C'est une ____ : rien n'a été inventé.`,cue:`(vrai, histoire: true story)`,answer:`histoire vraie`,wrong:[`vraie histoire`,`histoire vrai`,`vraies histoire`],en:`It's a true story: nothing has been made up.`,why:`After the noun, vrai means "true, factual"; before it, "real, genuine".`},{id:`pure-perte`,fr:`Cette réunion, c'est une ____ de temps.`,cue:`(pur, perte: sheer waste)`,answer:`pure perte`,wrong:[`perte pure`,`pur perte`,`pures perte`],en:`This meeting is a sheer waste of time.`,why:`Before the noun, pur means "sheer, utter"; after it, "pure, clean".`},{id:`air-pur`,fr:`En montagne, on respire un ____.`,cue:`(pur, air: clean air)`,answer:`air pur`,wrong:[`pur air`,`air pure`,`pure air`],en:`In the mountains, you breathe clean air.`,why:`After the noun, pur means "pure, unpolluted"; air is masculine.`}]},{id:`prepositions-verbes`,title:`Complète avec la bonne préposition`,en:`Complete with the right preposition`,level:4,items:[{id:`tenir-a`,fr:`Je tiens ____ vous remercier pour votre accueil.`,answer:`à`,wrong:[`de`,`pour`,`en`],en:`I'd really like to thank you for your welcome.`,why:`Tenir à + infinitive: to be keen to, to insist on.`},{id:`s-interesser-a-la`,fr:`Elle s'intéresse beaucoup ____ politique internationale.`,answer:`à la`,wrong:[`de la`,`pour la`,`en`],en:`She is very interested in international politics.`,why:`S'intéresser à quelque chose; à + la doesn't contract.`},{id:`renoncer-au`,fr:`Il a fini par renoncer ____ poste à l'étranger.`,answer:`au`,wrong:[`à le`,`du`,`de`],en:`He eventually gave up on the job abroad.`,why:`Renoncer à; à + le contracts to au.`},{id:`s-attendre-a`,fr:`Je ne m'attendais pas du tout ____ cette réaction de sa part.`,answer:`à`,wrong:[`de`,`pour`,`sur`],en:`I really wasn't expecting that reaction from him.`,why:`S'attendre à quelque chose: to expect something.`},{id:`consister-a`,fr:`Le poste consiste ____ gérer les relations avec les clients.`,answer:`à`,wrong:[`en`,`de`,`dans`],en:`The job consists in managing customer relations.`,why:`Consister à + infinitive (consister en + noun).`},{id:`consister-en`,fr:`Le menu consiste ____ trois plats et un dessert.`,answer:`en`,wrong:[`à`,`de`,`dans`],en:`The menu consists of three courses and a dessert.`,why:`Consister en + noun: to be made up of ("consister de" is an anglicism).`},{id:`reussir-a`,fr:`Elle a réussi ____ convaincre le jury.`,answer:`à`,wrong:[`de`,`pour`,`en`],en:`She managed to convince the jury.`,why:`Réussir à + infinitive: to manage to.`},{id:`aider-a`,fr:`Il m'a aidée ____ remplir le formulaire.`,answer:`à`,wrong:[`de`,`en`,`avec`],en:`He helped me fill in the form.`,why:`Aider quelqu'un à + infinitive.`},{id:`se-souvenir-de`,fr:`Tu te souviens ____ notre premier voyage en Italie ?`,answer:`de`,wrong:[`à`,`du`,`sur`],en:`Do you remember our first trip to Italy?`,why:`Se souvenir de quelque chose; no contraction before notre.`},{id:`se-mefier-des`,fr:`Méfie-toi ____ promesses trop belles pour être vraies.`,answer:`des`,wrong:[`aux`,`de les`,`à`],en:`Beware of promises that are too good to be true.`,why:`Se méfier de; de + les contracts to des.`},{id:`dependre-du`,fr:`Tout dépend ____ budget dont nous disposerons.`,answer:`du`,wrong:[`au`,`de le`,`sur le`],en:`It all depends on the budget we will have.`,why:`Dépendre de (never "sur"); de + le contracts to du.`},{id:`s-occuper-du`,fr:`C'est ma collègue qui s'occupe ____ recrutement.`,answer:`du`,wrong:[`au`,`de le`,`pour le`],en:`My colleague is the one who handles recruitment.`,why:`S'occuper de; de + le contracts to du.`},{id:`se-moquer-de`,fr:`Arrête de te moquer ____ lui, il fait de son mieux.`,answer:`de`,wrong:[`à`,`sur`,`contre`],en:`Stop making fun of him, he's doing his best.`,why:`Se moquer de quelqu'un: to make fun of someone.`},{id:`se-passer-de`,fr:`Je ne peux pas me passer ____ mon téléphone.`,answer:`de`,wrong:[`sans`,`à`,`du`],en:`I can't do without my phone.`,why:`Se passer de quelque chose: to do without it.`},{id:`demander-au`,fr:`J'ai demandé ____ directeur de m'accorder un jour de congé.`,answer:`au`,wrong:[`le`,`du`,`à le`],en:`I asked the manager to give me a day off.`,why:`Demander à quelqu'un de faire quelque chose; à + le contracts to au.`},{id:`empecher-de`,fr:`Le bruit des travaux m'a empêché ____ dormir.`,answer:`de`,wrong:[`à`,`pour`,`sans`],en:`The noise from the building work kept me awake.`,why:`Empêcher quelqu'un de + infinitive.`},{id:`manquer-a`,fr:`Depuis que j'habite à Montréal, ____ énormément.`,cue:`(I miss my family)`,answer:`ma famille me manque`,wrong:[`je manque ma famille`,`ma famille manque`,`je manque de famille`],en:`Since I've been living in Montreal, I've missed my family terribly.`,why:`Manquer à: the person you miss is the subject, and you are the indirect object (ma famille me manque).`},{id:`manquer-de`,fr:`Cette soupe manque ____ sel.`,answer:`de`,wrong:[`du`,`le`,`à`],en:`This soup needs more salt.`,why:`Manquer de + a noun with no article: to lack.`},{id:`penser-de`,fr:`Que penses-tu ____ son dernier film ?`,answer:`de`,wrong:[`à`,`sur`,`du`],en:`What do you think of his latest film?`,why:`Penser de = to have an opinion about.`},{id:`penser-a`,fr:`Je pense souvent ____ mes grands-parents.`,answer:`à`,wrong:[`de`,`aux`,`sur`],en:`I often think about my grandparents.`,why:`Penser à = to have someone or something in mind.`},{id:`commencer-par`,fr:`Commençons ____ faire le point sur le budget, puis nous passerons au calendrier.`,answer:`par`,wrong:[`en`,`avec`,`pour`],en:`Let's start by reviewing the budget, then we'll move on to the schedule.`,why:`Commencer par + infinitive: to start by doing.`},{id:`finir-par`,fr:`Après des années d'hésitation, il a fini ____ dire oui.`,answer:`par`,wrong:[`de`,`à`,`pour`],en:`After years of hesitation, he ended up saying yes.`,why:`Finir par + infinitive = to end up doing (finir de = to stop doing).`},{id:`jouer-du`,fr:`Elle joue ____ violon dans un orchestre amateur.`,answer:`du`,wrong:[`au`,`le`,`de`],en:`She plays the violin in an amateur orchestra.`,why:`Jouer de + instrument; de + le contracts to du.`},{id:`jouer-aux`,fr:`Le dimanche, ils jouent ____ cartes avec les voisins.`,answer:`aux`,wrong:[`des`,`les`,`à les`],en:`On Sundays they play cards with the neighbours.`,why:`Jouer à + game; à + les contracts to aux.`}]},{id:`negation-soutenue`,title:`Complète avec la bonne négation`,en:`Complete with the right negation`,level:4,items:[{id:`guere`,fr:`Je n'ai ____ le temps de lire ces jours-ci.`,cue:`(hardly)`,answer:`guère`,wrong:[`pas guère`,`aucun`,`rien`],en:`I hardly have time to read these days.`,why:`Ne… guère = hardly, scarcely (formal); it replaces pas.`},{id:`nullement`,fr:`Il ne s'est ____ excusé : il a fait comme si de rien n'était.`,cue:`(not in the least)`,answer:`nullement`,accept:[`aucunement`,`pas du tout`],wrong:[`pas nullement`,`guère`,`aucun`],en:`He didn't apologise in the slightest: he acted as if nothing had happened.`,why:`Ne… nullement = not at all (formal); nullement replaces pas.`},{id:`point`,fr:`Je ne l'ai ____ revu depuis des années.`,cue:`(not, literary)`,answer:`point`,wrong:[`pas point`,`nul`,`aucun`],en:`I haven't seen him again for years.`,why:`Ne… point is the literary equivalent of ne… pas.`},{id:`aucune-reponse`,fr:`Nous n'avons reçu ____ réponse à notre courrier.`,answer:`aucune`,wrong:[`aucun`,`aucunes`,`pas aucune`],en:`We received no reply to our letter.`,why:`Ne… aucun(e) agrees with the noun (réponse is feminine), stays singular and never takes pas.`},{id:`nulle-trace`,fr:`Il n'y a ____ trace de lui dans les registres.`,cue:`(no… whatsoever, literary)`,answer:`nulle`,accept:[`aucune`],wrong:[`nul`,`pas nulle`,`nulles`],en:`There is no trace of him whatsoever in the records.`,why:`Nul(le), like aucun(e), agrees with the noun and replaces pas.`},{id:`nulle-part`,fr:`J'ai cherché mes clés partout, mais je ne les trouve ____.`,cue:`(anywhere)`,answer:`nulle part`,wrong:[`pas nulle part`,`aucune part`,`nul part`],en:`I've looked for my keys everywhere, but I can't find them anywhere.`,why:`Ne… nulle part = nowhere, not anywhere; no pas.`},{id:`ne-que-eau`,fr:`Il ne boit ____ de l'eau pendant la semaine.`,cue:`(only)`,answer:`que`,wrong:[`pas que`,`seulement`,`jamais`],en:`He drinks only water during the week.`,why:`Ne… que means 'only' and keeps the article: il ne boit que de l'eau.`},{id:`ne-fait-que`,fr:`Depuis le début de la réunion, il ne fait ____ se plaindre.`,cue:`(nothing but)`,answer:`que`,wrong:[`pas que`,`seulement`,`rien`],en:`Since the meeting started, he's done nothing but complain.`,why:`Ne faire que + infinitive = to do nothing but.`},{id:`ni-ni-ne`,fr:`Ni mon frère ni ma sœur ____ venus à la réunion.`,answer:`ne sont`,wrong:[`ne sont pas`,`sont`,`n'est`],en:`Neither my brother nor my sister came to the meeting.`,why:`Ni… ni… takes ne before the verb but no pas; two subjects make it plural.`},{id:`ni-freres-ni-soeurs`,fr:`Je n'ai ____ frères ni sœurs.`,answer:`ni`,wrong:[`pas`,`aucun`,`ne`],en:`I have no brothers or sisters.`,why:`Ni… ni… with ne before the verb and no pas or article.`},{id:`aucun-candidat`,fr:`Aucun candidat ____ le niveau requis.`,answer:`n'avait`,wrong:[`avait`,`n'avait pas`,`n'avait point`],en:`No candidate had the required level.`,why:`Aucun as a subject takes ne before the verb, but never pas.`},{id:`sans-rien-dire`,fr:`Elle est partie sans ____ dire.`,answer:`rien`,wrong:[`ne rien`,`pas rien`,`rien ne`],en:`She left without saying anything.`,why:`Sans is already negative: sans rien dire, with no ne.`},{id:`sans-jamais`,fr:`Elle travaille douze heures par jour sans ____ se plaindre.`,cue:`(ever)`,answer:`jamais`,wrong:[`ne jamais`,`pas jamais`,`jamais ne`],en:`She works twelve hours a day without ever complaining.`,why:`Sans carries the negation: sans jamais, sans rien, sans personne, with no ne.`},{id:`avant-qu-il-ne`,fr:`Partons avant qu'il ____ à pleuvoir.`,answer:`ne commence`,accept:[`commence`],wrong:[`ne commence pas`,`ne commencera`,`commencera`],en:`Let's go before it starts raining.`,why:`After avant que, ne is expletive (optional, not negative); adding pas would change the meaning.`},{id:`a-moins-qu-il-n-y-ait`,fr:`Je viendrai, à moins qu'il ____ un imprévu.`,answer:`n'y ait`,accept:[`y ait`],wrong:[`n'y ait pas`,`y a`,`n'y a`],en:`I'll come, unless something unexpected comes up.`,why:`À moins que + subjunctive, with an optional expletive ne and no pas.`},{id:`craindre-que-ne`,fr:`Je crains qu'il ____ trop tard pour changer d'avis.`,answer:`ne soit`,accept:[`soit`],wrong:[`ne soit pas`,`n'est`,`est`],en:`I'm afraid it's too late to change your mind.`,why:`After craindre que, the subjunctive often takes an expletive ne; pas would make it negative.`},{id:`plus-qu-on-ne-pense`,fr:`Le projet est plus complexe qu'on ____ le pense.`,answer:`ne`,wrong:[`ne pas`,`pas`,`ne plus`],en:`The project is more complex than people think.`,why:`After a comparison (plus… que), formal French adds an expletive ne with no negative meaning.`},{id:`ne-saurais`,fr:`Je ____ saurais vous dire à quelle heure il rentrera.`,answer:`ne`,wrong:[`ne pas`,`pas`,`ne point`],en:`I couldn't tell you what time he'll be back.`,why:`With savoir in the conditional, formal French uses ne on its own: je ne saurais.`},{id:`ne-cesse-de`,fr:`Il ne cesse ____ pleuvoir depuis lundi.`,answer:`de`,accept:[`pas de`],wrong:[`à`,`pour`,`que`],en:`It hasn't stopped raining since Monday.`,why:`Ne cesser de + infinitive (formal, no pas needed) = to keep on doing.`}]}],o=[{id:`subjonctif-conjonctions`,title:`Conjugue le verbe après la conjonction`,en:`Conjugate the verb after the conjunction`,level:4,items:[{id:`pour-que`,fr:`Je vous envoie le document ce soir pour que vous ____ le temps de le relire.`,cue:`(avoir)`,answer:`ayez`,wrong:[`avez`,`aurez`,`auriez`,`ayiez`],en:`I'm sending you the document this evening so that you have time to read it over.`,why:`Pour que always takes the subjunctive: que vous ayez.`},{id:`afin-que`,fr:`Le texte a été simplifié afin que tout le monde le ____.`,cue:`(comprendre)`,answer:`comprenne`,wrong:[`comprend`,`comprendra`,`comprendrait`,`comprennent`],en:`The text was simplified so that everyone could understand it.`,why:`Afin que + subjunctive: que tout le monde comprenne.`},{id:`bien-que`,fr:`Bien que le projet ____ en retard, la direction reste optimiste.`,cue:`(être)`,answer:`soit`,wrong:[`est`,`sera`,`était`,`soient`],en:`Although the project is behind schedule, the management remains optimistic.`,why:`Bien que always takes the subjunctive.`},{id:`bien-que-passe`,fr:`Bien qu'ils ____ toute la nuit, ils n'ont pas trouvé de solution.`,cue:`(travailler)`,answer:`aient travaillé`,wrong:[`ont travaillé`,`avaient travaillé`,`travaillaient`,`auraient travaillé`],en:`Although they worked all night, they didn't find a solution.`,why:`Bien que + past subjunctive for an action already completed.`},{id:`quoique-passe`,fr:`Quoiqu'elle ____ le meilleur dossier, elle n'a pas été retenue.`,cue:`(avoir)`,answer:`ait eu`,accept:[`ait`],wrong:[`a eu`,`avait eu`,`aurait eu`,`aie eu`],en:`Although she had the strongest application, she wasn't selected.`,why:`Quoique + subjunctive; the past subjunctive (ait eu) for a completed fact.`},{id:`avant-que-ne`,fr:`Il faut agir avant qu'il ____ trop tard.`,cue:`(être)`,answer:`ne soit`,accept:[`soit`],wrong:[`n'est`,`ne sera`,`ne serait`,`ne soient`],en:`We must act before it's too late.`,why:`Avant que + subjunctive; this ne is the optional explétif, not a negation.`},{id:`a-moins-que`,fr:`Nous partirons à 7 h, à moins que tu ____ une meilleure idée.`,cue:`(avoir)`,answer:`aies`,accept:[`n'aies`],wrong:[`as`,`auras`,`aurais`,`ait`],en:`We'll leave at 7, unless you have a better idea.`,why:`À moins que + subjunctive: que tu aies.`},{id:`a-moins-que-ne`,fr:`Nous maintiendrons la grève, à moins que vous ne ____ une solution acceptable.`,cue:`(proposer)`,answer:`proposiez`,wrong:[`proposez`,`proposerez`,`proposeriez`,`proposent`],en:`We'll keep up the strike unless you put forward an acceptable solution.`,why:`À moins que + subjunctive (the ne is optional and not negative).`},{id:`sans-que`,fr:`Il est parti sans que nous nous en ____ compte.`,cue:`(se rendre)`,answer:`rendions`,accept:[`soyons rendu`],wrong:[`rendons`,`rendrions`,`rendrons`,`rendiez`],en:`He left without our noticing.`,why:`Sans que + subjunctive: que nous nous en rendions compte.`},{id:`jusqu-a-ce-que`,fr:`Je resterai à ses côtés jusqu'à ce qu'elle ____ mieux.`,cue:`(aller)`,answer:`aille`,wrong:[`va`,`ira`,`irait`,`aie`],en:`I'll stay by her side until she's feeling better.`,why:`Jusqu'à ce que + subjunctive: qu'elle aille.`},{id:`pourvu-que`,fr:`J'accepte de vous prêter la salle, pourvu que vous la ____ propre.`,cue:`(laisser)`,answer:`laissiez`,wrong:[`laissez`,`laisserez`,`laisseriez`,`laissaient`],en:`I'm happy to lend you the room, provided you leave it clean.`,why:`Pourvu que + subjunctive: que vous laissiez.`},{id:`de-peur-que`,fr:`Elle n'a rien dit de peur que son chef ne la ____ pas au sérieux.`,cue:`(prendre)`,answer:`prenne`,wrong:[`prend`,`prendra`,`prendrait`,`prenait`],en:`She said nothing for fear that her boss wouldn't take her seriously.`,why:`De peur que + subjunctive (here with a real negation, ne… pas).`},{id:`a-condition-que`,fr:`Le contrat sera renouvelé à condition que les objectifs ____ atteints.`,cue:`(être)`,answer:`soient`,accept:[`aient été`],wrong:[`sont`,`seront`,`seraient`,`soit`],en:`The contract will be renewed on condition that the targets are met.`,why:`À condition que + subjunctive.`},{id:`en-attendant-que`,fr:`Nous avons feuilleté des magazines en attendant que le médecin nous ____.`,cue:`(recevoir)`,answer:`reçoive`,wrong:[`reçoit`,`recevait`,`recevra`,`reçoivent`],en:`We leafed through magazines while waiting for the doctor to see us.`,why:`En attendant que + subjunctive.`},{id:`apres-que-futur`,fr:`On fera le ménage après que les invités ____.`,cue:`(partir)`,answer:`seront partis`,wrong:[`soient partis`,`sont partis`,`seraient partis`,`auront partis`],en:`We'll clean up after the guests have left.`,why:`Après que takes the indicative: here the futur antérieur, as they will have left.`},{id:`apres-que-passe`,fr:`Le scandale a éclaté juste après qu'il ____.`,cue:`(démissionner)`,answer:`a démissionné`,accept:[`avait démissionné`,`eut démissionné`],wrong:[`ait démissionné`,`aurait démissionné`,`aie démissionné`,`démissionne`],en:`The scandal broke just after he resigned.`,why:`Après que takes the indicative: qu'il a démissionné, not qu'il ait démissionné.`},{id:`alors-que`,fr:`Il continue de fumer sur son balcon alors qu'il ____ très bien que ça gêne les voisins.`,cue:`(savoir)`,answer:`sait`,wrong:[`sache`,`sais`,`saura`,`sachent`],en:`He keeps smoking on his balcony even though he knows full well it bothers the neighbours.`,why:`Alors que (contrast) takes the indicative.`},{id:`pendant-que`,fr:`Pendant que tu ____ les courses, je m'occupe du dîner.`,cue:`(faire)`,answer:`fais`,wrong:[`fasses`,`ferais`,`faisais`,`fait`],en:`While you do the shopping, I'll see to dinner.`,why:`Pendant que takes the indicative.`},{id:`tandis-que`,fr:`Elle adore la montagne, tandis que son mari ____ le froid en horreur.`,cue:`(avoir)`,answer:`a`,wrong:[`ait`,`as`,`aura`,`aient`],en:`She loves the mountains, whereas her husband can't stand the cold.`,why:`Tandis que (contrast) takes the indicative.`},{id:`depuis-que`,fr:`Depuis qu'elle ____ à Lyon, elle a complètement changé de rythme.`,cue:`(s'installer)`,answer:`s'est installée`,wrong:[`se soit installée`,`s'est installé`,`s'installera`,`s'était installée`],en:`Since she moved to Lyon, she has completely changed her pace of life.`,why:`Depuis que takes the indicative; installée agrees with elle.`},{id:`des-que`,fr:`Je vous rappellerai dès que nous ____ des nouvelles.`,cue:`(avoir)`,answer:`aurons`,wrong:[`ayons`,`avons`,`aurions`,`aurez`],en:`I'll call you back as soon as we have news.`,why:`Dès que takes the indicative, in the future when the main clause is in the future.`},{id:`une-fois-que`,fr:`Une fois que vous ____ le formulaire, envoyez-le au service RH.`,cue:`(remplir)`,answer:`aurez rempli`,accept:[`avez rempli`],wrong:[`ayez rempli`,`auriez rempli`,`remplissiez`,`aviez rempli`],en:`Once you've filled in the form, send it to HR.`,why:`Une fois que takes the indicative (futur antérieur or passé composé), never the subjunctive.`},{id:`meme-si`,fr:`Même s'il ____ beau demain, la randonnée est annulée.`,cue:`(faire)`,answer:`fait`,wrong:[`fasse`,`fera`,`ferait`,`faisait`],en:`Even if the weather is nice tomorrow, the hike is cancelled.`,why:`Même si works like si: present indicative, never the future or the subjunctive.`}]},{id:`subjonctif-ou-indicatif`,title:`Conjugue le verbe au bon mode`,en:`Put the verb in the right mood`,level:4,items:[{id:`je-pense-que`,fr:`Je pense que tu ____ raison sur ce point.`,cue:`(avoir)`,answer:`as`,accept:[`avais`,`as eu`],wrong:[`aies`,`ait`,`a`],en:`I think you're right on this point.`,why:`Je pense que (affirmative) takes the indicative.`},{id:`je-ne-pense-pas-que`,fr:`Je ne pense pas qu'il ____ le temps de tout finir avant vendredi.`,cue:`(avoir)`,answer:`ait`,wrong:[`a`,`aie`,`avait`],en:`I don't think he has time to finish everything before Friday.`,why:`Je ne pense pas que (a negated opinion, so doubt) takes the subjunctive.`},{id:`ne-pas-croire`,fr:`Je ne crois pas que nous ____ d'autre choix.`,cue:`(avoir)`,answer:`ayons`,accept:[`aurions`],wrong:[`avons`,`ayions`,`ayez`],en:`I don't think we have any other choice.`,why:`Je ne crois pas que (doubt) takes the subjunctive.`},{id:`trouver-que`,fr:`Je trouve que tu ____ trop dur avec lui.`,cue:`(être)`,answer:`es`,accept:[`étais`,`as été`],wrong:[`sois`,`soit`,`est`],en:`I think you're too hard on him.`,why:`Trouver que (an affirmative opinion) takes the indicative.`},{id:`etre-convaincu`,fr:`Je suis convaincu que nous ____ la bonne décision hier.`,cue:`(prendre)`,answer:`avons pris`,wrong:[`ayons pris`,`aurions pris`,`prenions`],en:`I'm convinced we made the right decision yesterday.`,why:`Être convaincu que (certainty) takes the indicative.`},{id:`pas-sur-que`,fr:`Je ne suis pas sûre que cette solution ____ la meilleure.`,cue:`(être)`,answer:`soit`,accept:[`serait`],wrong:[`est`,`sois`,`soient`],en:`I'm not sure this solution is the best one.`,why:`Ne pas être sûr que (doubt) takes the subjunctive.`},{id:`il-est-probable`,fr:`Il est probable qu'il ____ son train : il ne répond pas au téléphone.`,cue:`(rater)`,answer:`a raté`,accept:[`rate`],wrong:[`ait raté`,`aurait raté`,`aie raté`],en:`He has probably missed his train: he isn't answering his phone.`,why:`Il est probable que (a strong likelihood) takes the indicative.`},{id:`il-est-possible`,fr:`Il est possible que la ministre ____ sa démission dès demain.`,cue:`(remettre)`,answer:`remette`,wrong:[`remet`,`remettra`,`remettrait`],en:`The minister may hand in her resignation as early as tomorrow.`,why:`Il est possible que (a mere possibility) takes the subjunctive.`},{id:`peu-probable`,fr:`Il est peu probable que la loi ____ adoptée avant l'été.`,cue:`(être)`,answer:`soit`,wrong:[`sera`,`est`,`soient`],en:`It's unlikely the law will be passed before the summer.`,why:`Il est peu probable que (doubt) takes the subjunctive, unlike il est probable que.`},{id:`il-est-clair`,fr:`Il est clair que, pour l'instant, la direction ne ____ pas reculer.`,cue:`(vouloir)`,answer:`veut`,accept:[`voudra`],wrong:[`veuille`,`veux`,`veulent`],en:`It's clear that, for now, the management doesn't want to back down.`,why:`Il est clair que (certainty) takes the indicative.`},{id:`il-me-semble-que`,fr:`Il me semble que le loyer ____ beaucoup augmenté cette année.`,cue:`(avoir)`,answer:`a`,wrong:[`ait`,`est`,`aie`],en:`It seems to me the rent has gone up a lot this year.`,why:`Il me semble que takes the indicative.`},{id:`esperer-que`,fr:`J'espère qu'elle ____ venir à notre mariage en juin.`,cue:`(pouvoir)`,answer:`pourra`,accept:[`peut`],wrong:[`puisse`,`pourrait`,`puisses`],en:`I hope she'll be able to come to our wedding in June.`,why:`Espérer que takes the indicative (often the future), never the subjunctive.`},{id:`souhaiter-que`,fr:`Nous souhaitons que chaque salarié ____ accès à la formation.`,cue:`(avoir)`,answer:`ait`,wrong:[`a`,`aura`,`aurait`,`aie`],en:`We want every employee to have access to training.`,why:`Souhaiter que (a wish) takes the subjunctive, unlike espérer.`},{id:`exiger-que`,fr:`Le propriétaire exige que nous ____ le loyer avant le 5 du mois.`,cue:`(payer)`,answer:`payions`,wrong:[`payons`,`paierons`,`paierions`],en:`The landlord insists that we pay the rent before the 5th of the month.`,why:`Exiger que (a demand) takes the subjunctive: que nous payions.`},{id:`tenir-a-ce-que`,fr:`Mes parents tiennent à ce que nous ____ tous là pour leurs quarante ans de mariage.`,cue:`(être)`,answer:`soyons`,wrong:[`sommes`,`serons`,`soyions`,`serions`],en:`My parents insist that we all be there for their fortieth wedding anniversary.`,why:`Tenir à ce que (insistence) takes the subjunctive.`},{id:`s-attendre-a-ce-que`,fr:`Je ne m'attendais pas à ce qu'il ____ aussi vite.`,cue:`(réagir)`,answer:`réagisse`,accept:[`ait réagi`],wrong:[`réagit`,`réagirait`,`réagissait`,`réagira`],en:`I didn't expect him to react so quickly.`,why:`S'attendre à ce que + subjunctive.`},{id:`craindre-que`,fr:`Je crains que vous ____ pas toutes les informations nécessaires.`,cue:`(avoir)`,answer:`n'ayez`,wrong:[`n'avez`,`n'aurez`,`n'auriez`,`n'ayiez`],en:`I'm afraid you don't have all the necessary information.`,why:`Craindre que + subjunctive (here with a real negation, ne… pas).`},{id:`regretter-que`,fr:`Je regrette que vous le ____ ainsi.`,cue:`(prendre)`,answer:`preniez`,wrong:[`prenez`,`prendrez`,`prendriez`,`prenniez`],en:`I'm sorry you're taking it that way.`,why:`Regretter que (a feeling) takes the subjunctive.`},{id:`douter-que`,fr:`Je doute fort que le gouvernement ____ revenir sur sa décision.`,cue:`(vouloir)`,answer:`veuille`,wrong:[`veut`,`voudra`,`veuilles`],en:`I very much doubt the government will want to go back on its decision.`,why:`Douter que takes the subjunctive.`},{id:`superlatif`,fr:`C'est le meilleur roman que ____ jamais lu.`,cue:`(avoir)`,answer:`j'aie`,accept:[`j'ai`],wrong:[`j'avais`,`j'aurais`,`j'aies`],en:`It's the best novel I've ever read.`,why:`After a superlative (le meilleur… que), the subjunctive is the norm: que j'aie jamais lu.`},{id:`antecedent-incertain`,fr:`Nous cherchons un ou une stagiaire qui ____ parler allemand couramment.`,cue:`(savoir)`,answer:`sache`,accept:[`sait`,`saurait`],wrong:[`saches`,`sachent`,`savait`],en:`We're looking for an intern who can speak fluent German.`,why:`Such a person may not exist yet, so the subjunctive (qui sache) is the norm.`}]},{id:`hypotheses-si`,title:`Mets le verbe au temps qui convient`,en:`Put the verb in the right tense`,level:3,items:[{id:`present-futur`,fr:`Si le comité valide le budget, les travaux ____ en mars.`,cue:`(commencer)`,answer:`commenceront`,accept:[`commencent`],wrong:[`commenceraient`,`commençaient`,`auraient commencé`,`commencèrent`],en:`If the committee approves the budget, the work will start in March.`,why:`Si + présent → futur (or présent) in the main clause.`},{id:`present-futur-etre`,fr:`Si la grève continue, nous ____ obligés d'annuler le festival.`,cue:`(être)`,answer:`serons`,accept:[`sommes`],wrong:[`serions`,`étions`,`soyons`],en:`If the strike goes on, we'll have to cancel the festival.`,why:`Si + présent → futur (or présent).`},{id:`present-imperatif`,fr:`Si vous ____ des questions, n'hésitez pas à me contacter.`,cue:`(avoir)`,answer:`avez`,wrong:[`aurez`,`auriez`,`ayez`],en:`If you have any questions, don't hesitate to contact me.`,why:`Si + présent → impératif; never the future after si.`},{id:`present-imperatif-devoir`,fr:`Si tu ____ partir plus tôt, préviens ton chef.`,cue:`(devoir)`,answer:`dois`,accept:[`devais`],wrong:[`devras`,`devrais`,`doives`],en:`If you have to leave early, let your manager know.`,why:`Si + présent → impératif.`},{id:`present-present`,fr:`Si on ____ trop les prix, les clients vont voir ailleurs.`,cue:`(augmenter)`,answer:`augmente`,wrong:[`augmentera`,`augmenterait`,`augmentait`,`augmentes`],en:`If you put prices up too much, customers go elsewhere.`,why:`A general truth: si + présent → présent.`},{id:`passe-compose-imperatif`,fr:`Si tu ____ ton rapport avant midi, envoie-le-moi tout de suite.`,cue:`(terminer)`,answer:`as terminé`,accept:[`termines`],wrong:[`auras terminé`,`aurais terminé`,`avais terminé`,`aies terminé`],en:`If you've finished your report before noon, send it to me straight away.`,why:`Si + passé composé (an action already done) → impératif.`},{id:`imparfait-avoir`,fr:`Si ____ ton âge, je partirais un an à l'étranger.`,cue:`(avoir)`,answer:`j'avais`,wrong:[`j'aurais`,`j'ai`,`j'aurai`],en:`If I were your age, I'd go abroad for a year.`,why:`Si + imparfait → conditionnel présent; never si + conditionnel.`},{id:`imparfait-elle`,fr:`Si elle ____ plus confiance en elle, elle postulerait à ce poste.`,cue:`(avoir)`,answer:`avait`,wrong:[`aurait`,`a`,`aura`,`avais`],en:`If she had more self-confidence, she'd apply for that job.`,why:`Si + imparfait, never si + conditionnel ('si elle aurait').`},{id:`imparfait-etre`,fr:`S'il ____ là, il saurait quoi faire.`,cue:`(être)`,answer:`était`,wrong:[`serait`,`est`,`sera`,`étais`],en:`If he were here, he'd know what to do.`,why:`Si + imparfait (s'il était) → conditionnel présent.`},{id:`imparfait-y-avoir`,fr:`S'il ____ moins de monde, on pourrait trouver une table.`,cue:`(y avoir)`,answer:`y avait`,wrong:[`y aurait`,`y a`,`y aura`],en:`If there were fewer people, we could find a table.`,why:`Si + imparfait (il y avait) → conditionnel présent (on pourrait).`},{id:`imparfait-pouvoir`,fr:`Si vous ____ me rappeler avant 18 h, ce serait parfait.`,cue:`(pouvoir)`,answer:`pouviez`,wrong:[`pourriez`,`pourrez`,`puissiez`],en:`If you could call me back before 6 pm, that would be perfect.`,why:`Si + imparfait → conditionnel (ce serait); 'si vous pourriez' is wrong.`},{id:`imparfait-cond`,fr:`Si les loyers étaient moins chers, beaucoup de jeunes ____ en centre-ville.`,cue:`(habiter)`,answer:`habiteraient`,wrong:[`habiteront`,`habitaient`,`habitent`,`habiterait`],en:`If rents were cheaper, many young people would live in the city centre.`,why:`Si + imparfait → conditionnel présent.`},{id:`suggestion`,fr:`Et si on ____ le week-end à la campagne ?`,cue:`(passer)`,answer:`passait`,wrong:[`passerait`,`passera`,`passerais`],en:`How about spending the weekend in the country?`,why:`Si on + imparfait on its own makes a suggestion.`},{id:`pqp-partir`,fr:`Si nous ____ plus tôt, nous n'aurions pas raté le dernier métro.`,cue:`(partir)`,answer:`étions partis`,accept:[`étions parties`],wrong:[`serions partis`,`avions partis`,`étions parti`,`sommes partis`],en:`If we'd left earlier, we wouldn't have missed the last metro.`,why:`Si + plus-que-parfait → conditionnel passé (an unreal past).`},{id:`condpasse-venir`,fr:`Si tu m'avais dit que tu arrivais, ____ te chercher à l'aéroport.`,cue:`(venir)`,answer:`je serais venu`,accept:[`je serais venue`],wrong:[`j'aurais venu`,`je serai venu`,`j'étais venu`,`je serais venus`],en:`If you'd told me you were arriving, I'd have come to pick you up at the airport.`,why:`Si + plus-que-parfait → conditionnel passé; venir takes être.`},{id:`pqp-negatif`,fr:`S'ils avaient investi à temps, l'entreprise ____ pas fait faillite.`,cue:`(avoir)`,answer:`n'aurait`,wrong:[`n'avait`,`n'aura`,`ne serait`,`n'aurais`],en:`If they had invested in time, the company wouldn't have gone bankrupt.`,why:`Si + plus-que-parfait → conditionnel passé: elle n'aurait pas fait faillite.`},{id:`condpasse-pronominal`,fr:`Si elle s'était renseignée, elle ne ____ pas fait avoir.`,cue:`(se faire avoir)`,answer:`se serait`,wrong:[`s'aurait`,`se serais`,`s'était`,`se sera`],en:`If she'd looked into it, she wouldn't have been taken in.`,why:`Conditionnel passé of a pronominal verb: être as auxiliary (se serait fait avoir).`},{id:`meme-si-pqp`,fr:`Même si j'avais su, je ____ rien changé.`,cue:`(avoir)`,answer:`n'aurais`,wrong:[`n'avais`,`n'aurai`,`ne serais`,`n'ai`],en:`Even if I'd known, I wouldn't have changed anything.`,why:`Même si works like si: plus-que-parfait → conditionnel passé.`},{id:`mixte-pqp-present`,fr:`Si j'avais accepté ce poste à Montréal, ____ au Canada aujourd'hui.`,cue:`(vivre)`,answer:`je vivrais`,wrong:[`j'aurais vécu`,`je vivrai`,`je vivais`,`j'avais vécu`],en:`If I'd accepted that job in Montreal, I'd be living in Canada today.`,why:`Mixed: a past condition (plus-que-parfait), a present result (conditionnel présent).`},{id:`mixte-imparfait-passe`,fr:`Si Julie parlait allemand, elle ____ le poste à Berlin l'an dernier.`,cue:`(obtenir)`,answer:`aurait obtenu`,wrong:[`obtiendrait`,`avait obtenu`,`aura obtenu`,`aurait obtenue`],en:`If Julie spoke German, she would have got the job in Berlin last year.`,why:`Mixed: a permanent condition (imparfait), a past result (conditionnel passé).`},{id:`au-cas-ou`,fr:`Garde bien ce ticket, au cas où tu ____ rendre la veste.`,cue:`(devoir)`,answer:`devrais`,wrong:[`dois`,`devras`,`doives`,`devais`],en:`Hang on to this receipt in case you have to return the jacket.`,why:`Au cas où takes the conditional.`},{id:`si-whether`,fr:`Je ne sais pas encore s'il ____ venir à la réunion de demain.`,cue:`(pouvoir)`,answer:`pourra`,accept:[`peut`,`pourrait`],wrong:[`puisse`,`pouvait`,`pourras`],en:`I don't know yet whether he'll be able to come to tomorrow's meeting.`,why:`Here si means 'whether' (an indirect question), so the future is fine.`}]}],s=e({DRILL_BY_ID:()=>l,DRILL_SETS:()=>c}),c=[...r,...o,...t,...n,...i,...a],l=Object.fromEntries(c.map(e=>[e.id,e]));export{s as n,c as t};